(window.SLIDES = window.SLIDES || []).push(
  // ── Grundgesetz & Grundrechte ──
  { id: "pde-001", cat: "politik", topic: "Grundgesetz", type: "event", emoji: "📜", level: 1, year: "1949",
    title: "23. Mai 1949: Das Grundgesetz tritt in Kraft",
    text: "Der Parlamentarische Rat unter Konrad Adenauer erarbeitete in Bonn das Grundgesetz. Bewusst nicht „Verfassung“ genannt: Es sollte nur bis zur Wiedervereinigung gelten.",
    more: "Die Väter und Mütter des GG zogen Lehren aus Weimar: starker Kanzler, schwacher Präsident, Grundrechte direkt einklagbar, Parteien unter Verfassungsschutz. 1990 trat die DDR nach Art. 23 bei – das Provisorium wurde zur gesamtdeutschen Verfassung." },
  { id: "pde-002", cat: "politik", topic: "Grundgesetz", type: "fact", emoji: "🛡️", level: 1,
    title: "Art. 1: Die Würde des Menschen ist unantastbar",
    text: "Der erste Satz des Grundgesetzes ist sein Fundament. Die Menschenwürde darf nicht gegen andere Werte abgewogen werden – sie ist absolut. Alle staatliche Gewalt muss sie achten und schützen.",
    more: "Praxisbeispiel: 2006 kippte das Bundesverfassungsgericht das Luftsicherheitsgesetz. Ein entführtes Passagierflugzeug abzuschießen, um andere zu retten, würde Unschuldige zum bloßen Objekt staatlichen Handelns machen – Leben darf nicht gegen Leben verrechnet werden." },
  { id: "pde-003", cat: "politik", topic: "Grundgesetz", type: "flashcard", emoji: "🏛️", level: 1,
    term: "Art. 20 GG – Staatsstrukturprinzipien",
    def: "Deutschland ist ein **demokratischer** und **sozialer Bundesstaat**; zudem gilt das **Rechtsstaatsprinzip** (Gewaltenteilung, Bindung an Recht und Gesetz). Abs. 4 gewährt ein Widerstandsrecht als letztes Mittel.",
    example: "Eselsbrücke „DReSoBu“: Demokratie, Rechtsstaat, Sozialstaat, Bundesstaat (plus Republik)." },
  { id: "pde-004", cat: "politik", topic: "Grundgesetz", type: "fact", emoji: "♾️", level: 2,
    title: "Ewigkeitsklausel: Was nie geändert werden darf",
    text: "Art. 79 Abs. 3 verbietet Änderungen, die die Gliederung in Länder, die Mitwirkung der Länder an der Gesetzgebung oder die Grundsätze von Art. 1 und Art. 20 berühren – selbst mit 100 % Zustimmung.",
    more: "Lehre aus 1933: Das Ermächtigungsgesetz war formal legal und hebelte trotzdem die Weimarer Verfassung aus. Die Ewigkeitsklausel soll verhindern, dass eine Mehrheit die Demokratie „legal“ abschafft." },
  { id: "pde-005", cat: "politik", topic: "Grundgesetz", type: "quiz", emoji: "⚖️", level: 1,
    q: "Welche Mehrheit braucht eine Änderung des Grundgesetzes?",
    options: ["Absolute Mehrheit im Bundestag", "Zwei Drittel in Bundestag und Bundesrat", "Volksabstimmung mit einfacher Mehrheit", "Drei Viertel des Bundestags"],
    answer: 1,
    explain: "Art. 79 Abs. 2: zwei Drittel der Mitglieder des Bundestags UND zwei Drittel der Stimmen des Bundesrats. Eine Volksabstimmung ist auf Bundesebene nicht vorgesehen." },
  { id: "pde-006", cat: "politik", topic: "Grundgesetz", type: "truefalse", emoji: "🗳️", level: 1,
    q: "Das Grundgesetz sieht bundesweite Volksentscheide über beliebige Gesetze vor.",
    answer: false,
    explain: "Auf Bundesebene gibt es nur eine Volksabstimmung bei der Neugliederung des Bundesgebiets (Art. 29). Deutschland ist auf Bundesebene eine rein repräsentative Demokratie – in den Ländern gibt es dagegen Volksbegehren." },
  { id: "pde-007", cat: "politik", topic: "Grundgesetz", type: "flashcard", emoji: "🛡️", level: 2,
    term: "Wehrhafte (streitbare) Demokratie",
    def: "Die Demokratie verteidigt sich gegen ihre Feinde: Parteiverbot (Art. 21), Vereinsverbot (Art. 9), Grundrechtsverwirkung (Art. 18), Ewigkeitsklausel und Verfassungsschutz.",
    example: "Lehre aus Weimar: Keine Freiheit zur Abschaffung der Freiheit." },
  { id: "pde-008", cat: "politik", topic: "Grundgesetz", type: "quiz", emoji: "📖", level: 2,
    q: "Warum stehen die Grundrechte gleich am Anfang des Grundgesetzes (Art. 1–19)?",
    options: ["Aus redaktionellem Zufall", "Weil die Alliierten es so diktierten", "Weil sie nur für Deutsche gelten", "Als Signal: Der Staat ist für den Menschen da, nicht umgekehrt"],
    answer: 3,
    explain: "In der Weimarer Verfassung standen die Grundrechte im zweiten Hauptteil und galten eher als Programmsätze. Das GG stellt sie voran und erklärt sie zu unmittelbar geltendem Recht (Art. 1 Abs. 3)." },
  { id: "pde-009", cat: "politik", topic: "Grundgesetz", type: "truefalse", emoji: "👥", level: 2,
    q: "Alle Grundrechte gelten für jeden Menschen in Deutschland, unabhängig von der Staatsangehörigkeit.",
    answer: false,
    explain: "Es gibt Menschenrechte („Jeder hat…“, z. B. Meinungsfreiheit) und Deutschengrundrechte („Alle Deutschen…“), etwa Versammlungsfreiheit (Art. 8), Berufsfreiheit (Art. 12) und Freizügigkeit (Art. 11)." },
  { id: "pde-010", cat: "politik", topic: "Grundgesetz", type: "number", emoji: "✉️", level: 3,
    value: "< 2 %", label: "Erfolgsquote von Verfassungsbeschwerden",
    text: "Jeder kann Verfassungsbeschwerde erheben, wenn er sich in Grundrechten verletzt sieht – jährlich rund 5.000 Mal. Nur ein bis zwei Prozent haben Erfolg.",
    more: "Voraussetzung ist meist, dass der Rechtsweg erschöpft ist. Trotz der geringen Quote ist das Instrument mächtig: Einzelne Bürger haben so z. B. die Vorratsdatenspeicherung und Teile des Klimaschutzgesetzes zu Fall gebracht." },
  { id: "pde-011", cat: "politik", topic: "Grundgesetz", type: "whatif", emoji: "🔒", level: 3,
    q: "Was passiert, wenn der Bundestag mit Zweidrittelmehrheit die Länder abschaffen will?",
    steps: ["Änderung verstößt gegen Art. 79 Abs. 3", "Klage beim Bundesverfassungsgericht", "Gericht erklärt die Änderung für nichtig", "Bundesstaat bleibt bestehen"],
    text: "Selbst eine verfassungsändernde Mehrheit darf den Kern des GG nicht antasten. Ein „verfassungswidriges Verfassungsrecht“ ist möglich. Nur eine ganz neue Verfassung per Volksentscheid (Art. 146) könnte das GG ablösen." },
  { id: "pde-012", cat: "politik", topic: "Grundgesetz", type: "fact", emoji: "🌳", level: 2,
    title: "Art. 20a: Staatsziel Umwelt- und Tierschutz",
    text: "Seit 1994 schützt der Staat die natürlichen Lebensgrundlagen auch in Verantwortung für künftige Generationen, seit 2002 auch die Tiere. Staatsziele sind kein einklagbares Grundrecht, binden aber alle Staatsgewalt.",
    more: "Art. 20a war 2021 zentral für den Klimabeschluss des BVerfG: Wer heute zu wenig CO₂ einspart, verschiebt drastische Freiheitseinschränkungen auf die Jüngeren – das verletzt deren Grundrechte („intertemporale Freiheitssicherung“)." },

  // ── Bundestag ──
  { id: "pde-013", cat: "politik", topic: "Bundestag", type: "number", emoji: "🪑", level: 1,
    value: "630", label: "Sitze im Bundestag (seit der Wahl 2025)",
    text: "Durch die Wahlrechtsreform 2023 ist die Größe gedeckelt. 2021 saßen wegen Überhang- und Ausgleichsmandaten noch 736 Abgeordnete im Parlament – Rekord.",
    more: "Die Kanzlermehrheit (absolute Mehrheit der Mitglieder) liegt damit bei 316 Stimmen. Der Bundestag wird alle vier Jahre gewählt und ist das einzige direkt vom Volk gewählte Verfassungsorgan des Bundes." },
  { id: "pde-014", cat: "politik", topic: "Bundestag", type: "quiz", emoji: "🏛️", level: 1,
    q: "Welche Aufgabe hat der Bundestag NICHT?",
    options: ["Den Bundeskanzler wählen", "Gesetze beschließen", "Den Haushalt beschließen", "Den Bundespräsidenten allein wählen"],
    answer: 3,
    explain: "Den Bundespräsidenten wählt die Bundesversammlung: alle Bundestagsabgeordneten plus ebenso viele Delegierte der Landtage. Kanzlerwahl, Gesetzgebung, Budgetrecht und Kontrolle der Regierung sind Kernaufgaben des Bundestags." },
  { id: "pde-015", cat: "politik", topic: "Bundestag", type: "truefalse", emoji: "🔨", level: 1,
    q: "Der Bundestag kann sich mit Mehrheit selbst auflösen und Neuwahlen ansetzen.",
    answer: false,
    explain: "Ein Selbstauflösungsrecht gibt es nicht. Vorzeitige Neuwahlen gehen nur über die verlorene Vertrauensfrage (Art. 68) oder eine gescheiterte Kanzlerwahl (Art. 63) – jeweils entscheidet der Bundespräsident über die Auflösung." },
  { id: "pde-016", cat: "politik", topic: "Bundestag", type: "flashcard", emoji: "👥", level: 2,
    term: "Fraktion",
    def: "Zusammenschluss von mindestens 5 % der Bundestagsabgeordneten derselben Partei (oder nicht konkurrierender Parteien wie CDU/CSU). Fraktionen erhalten Redezeit, Ausschusssitze, Geld und Rederecht.",
    example: "CDU und CSU bilden seit 1949 eine Fraktionsgemeinschaft." },
  { id: "pde-017", cat: "politik", topic: "Bundestag", type: "flashcard", emoji: "🔍", level: 2,
    term: "Untersuchungsausschuss",
    def: "Ermittelt Missstände in Regierung und Verwaltung, mit gerichtsähnlichen Befugnissen (Zeugen, Akten). Muss eingesetzt werden, wenn ein Viertel der Abgeordneten es verlangt (Art. 44 GG).",
    example: "Minderheitenrecht: So kann die Opposition die Regierung kontrollieren, z. B. im Maut- oder Wirecard-Ausschuss." },
  { id: "pde-018", cat: "politik", topic: "Bundestag", type: "quiz", emoji: "🎤", level: 1,
    q: "Wer ist seit März 2025 Präsidentin des Bundestags?",
    options: ["Julia Klöckner", "Bärbel Bas", "Annalena Baerbock", "Saskia Esken"],
    answer: 0,
    explain: "Julia Klöckner (CDU) folgte auf Bärbel Bas (SPD), die Arbeitsministerin wurde. Traditionell stellt die stärkste Fraktion das Amt – protokollarisch das zweithöchste im Staat nach dem Bundespräsidenten." },

  // ── Bundesrat ──
  { id: "pde-019", cat: "politik", topic: "Bundesrat", type: "number", emoji: "🗺️", level: 1,
    value: "69", label: "Stimmen im Bundesrat",
    text: "Jedes Land hat je nach Einwohnerzahl 3 bis 6 Stimmen. NRW, Bayern, Baden-Württemberg und Niedersachsen haben 6, Bremen, Hamburg, Saarland und Mecklenburg-Vorpommern je 3.",
    more: "Die Staffelung bevorzugt kleine Länder: Bremen hat pro Einwohner etwa 13-mal so viel Gewicht wie NRW. Absichtlich: Der Bundesrat vertritt Länder, nicht Bürger. Die absolute Mehrheit liegt bei 35 Stimmen." },
  { id: "pde-020", cat: "politik", topic: "Bundesrat", type: "truefalse", emoji: "🗳️", level: 1,
    q: "Die Mitglieder des Bundesrats werden direkt vom Volk gewählt.",
    answer: false,
    explain: "Der Bundesrat besteht aus Mitgliedern der Landesregierungen (Ministerpräsidenten, Minister). Er ändert seine Zusammensetzung also mit jeder Landtagswahl – es gibt keine Legislaturperiode." },
  { id: "pde-021", cat: "politik", topic: "Bundesrat", type: "fact", emoji: "✋", level: 3,
    title: "Ein Land, eine Stimme: einheitliche Stimmabgabe",
    text: "Ein Land muss seine Stimmen einheitlich abgeben (Art. 51 Abs. 3). Sind sich Koalitionspartner im Land uneinig, enthält es sich meist – und das wirkt im Bundesrat wie ein Nein.",
    more: "Grund: Beschlüsse brauchen eine absolute Mehrheit (35 von 69), Enthaltungen zählen also faktisch dagegen. 2002 erklärte das BVerfG das Zuwanderungsgesetz für nichtig, weil Brandenburg uneinheitlich abgestimmt hatte. Koalitionsverträge der Länder regeln daher meist: Bei Streit Enthaltung." },
  { id: "pde-022", cat: "politik", topic: "Bundesrat", type: "quiz", emoji: "🔄", level: 2,
    q: "Wie wird der Präsident des Bundesrats bestimmt?",
    options: ["Direktwahl durch die Bürger", "Er wird vom Bundestag gewählt", "Jährlich rotierend unter den Ministerpräsidenten", "Der Ministerpräsident des größten Landes ist es dauerhaft"],
    answer: 2,
    explain: "Nach einer festen Reihenfolge (Königsteiner Abkommen) übernimmt jedes Jahr am 1. November ein anderer Ministerpräsident das Amt. Er vertritt auch den Bundespräsidenten, wenn dieser verhindert ist." },
  { id: "pde-023", cat: "politik", topic: "Bundesrat", type: "truefalse", emoji: "⚖️", level: 3,
    q: "Wenn die Regierungskoalition im Bund auch im Bundesrat eine Mehrheit hat, ist das der Normalfall.",
    answer: false,
    explain: "Wegen der vielen Landtagswahlen und bunten Landeskoalitionen haben Bundesregierungen meist keine eigene Bundesratsmehrheit. Wichtige Gesetze brauchen daher oft Kompromisse mit Ländern, in denen die Opposition mitregiert." },

  // ── Bundesregierung & Kanzler ──
  { id: "pde-024", cat: "politik", topic: "Bundesregierung", type: "flashcard", emoji: "🧭", level: 1,
    term: "Richtlinienkompetenz",
    def: "Der Bundeskanzler bestimmt die Richtlinien der Politik und trägt dafür die Verantwortung (Art. 65 GG). Innerhalb dieser Richtlinien führen die Minister ihre Ressorts selbstständig.",
    example: "Scholz nutzte sie 2022 offen, um die Laufzeitverlängerung von drei AKW bis April 2023 anzuordnen." },
  { id: "pde-025", cat: "politik", topic: "Bundesregierung", type: "flashcard", emoji: "🗂️", level: 2,
    term: "Ressortprinzip",
    def: "Jeder Bundesminister leitet sein Ministerium eigenständig und in eigener Verantwortung. Der Kanzler kann nicht in Einzelentscheidungen hineinregieren, wohl aber die Richtung vorgeben oder Minister entlassen lassen.",
    example: "Daneben gilt das Kollegialprinzip: Bei Streit zwischen Ministern entscheidet das Kabinett." },
  { id: "pde-026", cat: "politik", topic: "Bundesregierung", type: "quiz", emoji: "🗳️", level: 1,
    q: "Wie wird der Bundeskanzler gewählt?",
    options: ["Direkt vom Volk", "Vom Bundestag auf Vorschlag des Bundespräsidenten", "Von der Bundesversammlung", "Vom Bundesrat"],
    answer: 1,
    explain: "Art. 63: Der Bundespräsident schlägt vor, der Bundestag wählt ohne Aussprache mit absoluter Mehrheit seiner Mitglieder (Kanzlermehrheit). Gelingt das nicht, folgen weitere Wahlgänge." },
  { id: "pde-027", cat: "politik", topic: "Bundesregierung", type: "fact", emoji: "🔁", level: 2,
    title: "Konstruktives Misstrauensvotum",
    text: "Der Bundestag kann den Kanzler nur stürzen, indem er gleichzeitig mit absoluter Mehrheit einen Nachfolger wählt (Art. 67). Nur dagegen sein reicht nicht.",
    more: "Lehre aus Weimar: Dort stürzten Extremisten von links und rechts gemeinsam Regierungen, ohne selbst eine bilden zu können. Erfolgreich war es bisher nur einmal: 1982 wurde Helmut Kohl so Nachfolger von Helmut Schmidt. 1972 scheiterte Rainer Barzel gegen Willy Brandt knapp." },
  { id: "pde-028", cat: "politik", topic: "Bundesregierung", type: "whatif", emoji: "❓", level: 2,
    q: "Was passiert, wenn der Kanzler die Vertrauensfrage stellt und verliert?",
    steps: ["Keine Mehrheit für den Kanzler (Art. 68)", "Kanzler schlägt Auflösung vor", "Präsident kann binnen 21 Tagen auflösen", "Neuwahl innerhalb von 60 Tagen"],
    text: "Der Präsident muss nicht auflösen, er prüft die Lage. Die Vertrauensfrage wurde auch gezielt „verloren“, um Neuwahlen zu erreichen: 1972 (Brandt), 1982 (Kohl), 2005 (Schröder) und Dezember 2024 (Scholz)." },
  { id: "pde-029", cat: "politik", topic: "Bundesregierung", type: "truefalse", emoji: "🗓️", level: 1,
    q: "Die Amtszeit eines Bundeskanzlers ist auf zwei Wahlperioden begrenzt.",
    answer: false,
    explain: "Anders als beim Bundespräsidenten gibt es keine Begrenzung. Helmut Kohl regierte 16 Jahre (1982–1998), Angela Merkel ebenfalls 16 Jahre (2005–2021)." },
  { id: "pde-030", cat: "politik", topic: "Bundesregierung", type: "quiz", emoji: "💼", level: 2,
    q: "Wer bildet die Bundesregierung im Sinne des Grundgesetzes?",
    options: ["Kanzler und Bundesminister", "Kanzler, Minister und Staatssekretäre", "Alle Abgeordneten der Regierungsfraktionen", "Kanzler und Bundespräsident"],
    answer: 0,
    explain: "Art. 62: Die Bundesregierung besteht aus dem Bundeskanzler und den Bundesministern. Die Minister werden auf Vorschlag des Kanzlers vom Bundespräsidenten ernannt und entlassen." },

  // ── Bundespräsident ──
  { id: "pde-031", cat: "politik", topic: "Bundespräsident", type: "fact", emoji: "🎖️", level: 1,
    title: "Bundespräsident: Staatsoberhaupt mit wenig Macht",
    text: "Er vertritt Deutschland völkerrechtlich, unterzeichnet Gesetze, ernennt Kanzler, Minister und Richter. Gewählt wird er für fünf Jahre von der Bundesversammlung, einmalige Wiederwahl ist möglich.",
    more: "Bewusst schwach angelegt: Der Weimarer Reichspräsident konnte per Notverordnung regieren und den Reichstag auflösen – das ebnete Hitler den Weg. Die Macht des Bundespräsidenten liegt heute vor allem im Wort (Reden) und in Krisen (z. B. Parlamentsauflösung)." },
  { id: "pde-032", cat: "politik", topic: "Bundespräsident", type: "quiz", emoji: "✍️", level: 2,
    q: "Darf der Bundespräsident die Unterschrift unter ein Gesetz verweigern?",
    options: ["Nein, nie", "Ja, wenn er es politisch falsch findet", "Ja, wenn es offensichtlich verfassungswidrig ist", "Nur mit Zustimmung des Bundesrats"],
    answer: 2,
    explain: "Er hat ein formelles und (umstritten, aber praktiziert) begrenztes materielles Prüfungsrecht. Politische Ablehnung ist nicht erlaubt. Horst Köhler verweigerte 2006 zweimal die Unterschrift, etwa beim Flugsicherungsgesetz." },
  { id: "pde-033", cat: "politik", topic: "Bundespräsident", type: "number", emoji: "🏛️", level: 2,
    value: "12", label: "Bundespräsidenten seit 1949",
    text: "Von Theodor Heuss bis Frank-Walter Steinmeier, der seit 2017 im Amt ist und 2022 wiedergewählt wurde. Seine zweite Amtszeit endet regulär im März 2027.",
    more: "Die Bundesversammlung tritt nur zur Präsidentenwahl zusammen. Sie besteht aus allen Bundestagsabgeordneten und ebenso vielen von den Landtagen gewählten Delegierten – oft auch Prominente aus Sport und Kultur." },
  { id: "pde-034", cat: "politik", topic: "Bundespräsident", type: "truefalse", emoji: "🎖️", level: 1,
    q: "Der Bundespräsident ist Oberbefehlshaber der Bundeswehr.",
    answer: false,
    explain: "Im Frieden hat der Verteidigungsminister die Befehls- und Kommandogewalt (Art. 65a), im Verteidigungsfall geht sie auf den Bundeskanzler über (Art. 115b). Der Präsident hat keine militärische Befugnis." },

  // ── Bundesverfassungsgericht ──
  { id: "pde-035", cat: "politik", topic: "Verfassungsgericht", type: "fact", emoji: "⚖️", level: 1,
    title: "Bundesverfassungsgericht: Hüter der Verfassung",
    text: "Das Gericht in Karlsruhe hat 16 Richter in zwei Senaten. Sie werden je zur Hälfte von Bundestag und Bundesrat mit Zweidrittelmehrheit gewählt, für 12 Jahre ohne Wiederwahl.",
    more: "Die Zweidrittelmehrheit zwingt zum Kompromiss über Parteigrenzen hinweg – so soll niemand das Gericht allein besetzen. Seine Urteile binden alle Staatsorgane; es kann Gesetze für nichtig erklären. Im Dezember 2024 wurden Struktur und Wahlverfahren im GG verankert, um es gegen Angriffe abzusichern." },
  { id: "pde-036", cat: "politik", topic: "Verfassungsgericht", type: "quiz", emoji: "📋", level: 3,
    q: "Wer kann eine abstrakte Normenkontrolle beim BVerfG beantragen?",
    options: ["Jeder Bürger", "Jedes Amtsgericht", "Nur der Bundespräsident", "Bundesregierung, Landesregierung oder ein Viertel des Bundestags"],
    answer: 3,
    explain: "Die abstrakte Normenkontrolle prüft ein Gesetz ohne konkreten Fall. Antragsberechtigt sind Bundesregierung, Landesregierungen und ein Viertel der Bundestagsabgeordneten – ein wichtiges Werkzeug der Opposition." },
  { id: "pde-037", cat: "politik", topic: "Verfassungsgericht", type: "event", emoji: "💸", level: 2, year: "2023",
    title: "Karlsruhe kippt den Nachtragshaushalt 2021",
    text: "Am 15. November 2023 erklärte das BVerfG die Umwidmung von 60 Mrd. € ungenutzter Corona-Kredite in den Klima- und Transformationsfonds für verfassungswidrig.",
    more: "Folge: Der Ampel fehlten Milliarden für ihre Pläne, der Streit um Haushalt und Schuldenbremse eskalierte – eine Kette, die ein Jahr später zum Koalitionsbruch führte. Das Urteil zeigt: Notlagenkredite müssen an die Notlage gebunden und jährlich begründet sein." },
  { id: "pde-038", cat: "politik", topic: "Verfassungsgericht", type: "truefalse", emoji: "👨‍⚖️", level: 1,
    q: "Richter am Bundesverfassungsgericht werden auf Lebenszeit ernannt.",
    answer: false,
    explain: "Die Amtszeit beträgt 12 Jahre, längstens bis zum 68. Lebensjahr, eine Wiederwahl ist ausgeschlossen. Das stärkt die Unabhängigkeit: Niemand muss sich mit Blick auf eine zweite Amtszeit beliebt machen." },
  { id: "pde-039", cat: "politik", topic: "Verfassungsgericht", type: "order", emoji: "🔢", level: 2,
    q: "Ordne diese Urteile des BVerfG chronologisch.",
    items: ["KPD-Verbot", "Volkszählungsurteil (informationelle Selbstbestimmung)", "Klimabeschluss", "Urteil zum Nachtragshaushalt 2021"],
    explain: "KPD-Verbot 1956, Volkszählungsurteil 1983 (Grundlage des Datenschutzes), Klimabeschluss 2021, Haushaltsurteil 2023." },
  // ── Wahlrecht ──
  { id: "pde-040", cat: "politik", topic: "Wahlrecht", type: "fact", emoji: "🗳️", level: 1,
    title: "Erststimme und Zweitstimme",
    text: "Mit der Erststimme wählt man eine Person im eigenen Wahlkreis (299 Wahlkreise), mit der Zweitstimme eine Parteiliste. Die Zweitstimme entscheidet, wie viele Sitze eine Partei insgesamt bekommt.",
    more: "Häufiger Irrtum: Die Erststimme sei die wichtigere, weil sie „zuerst“ kommt. Tatsächlich bestimmt die Zweitstimme die Kräfteverhältnisse. Die Erststimme regelt vor allem, WER aus einer Partei einzieht. Das System heißt personalisierte Verhältniswahl." },
  { id: "pde-041", cat: "politik", topic: "Wahlrecht", type: "quiz", emoji: "🎯", level: 1,
    q: "Welche Stimme bestimmt die Sitzverteilung der Parteien im Bundestag?",
    options: ["Die Erststimme", "Die Zweitstimme", "Beide zu gleichen Teilen", "Die Stimme mit mehr Gesamtstimmen"],
    answer: 1,
    explain: "Die 630 Sitze werden nach dem Zweitstimmenanteil der Parteien verteilt (Verfahren Sainte-Laguë/Schepers), die über die 5-%-Hürde kommen. Die Erststimme besetzt Plätze innerhalb dieses Kontingents." },
  { id: "pde-042", cat: "politik", topic: "Wahlrecht", type: "whatif", emoji: "📉", level: 1,
    q: "Was passiert, wenn eine Partei 4,9 % der Zweitstimmen holt?",
    steps: ["Partei scheitert an der 5-%-Hürde", "Ausnahme nur bei 3 Direktmandaten", "Sonst: keine Sitze, Stimmen fallen weg", "Andere Parteien erhalten anteilig mehr Sitze"],
    text: "2025 scheiterten BSW (4,97 %) und FDP (4,3 %) knapp. Zusammen mit Kleinparteien blieb mehr als jede achte Zweitstimme ohne Wirkung. Deshalb reichten der Union mit 28,5 % rund ein Drittel der Sitze." },
  { id: "pde-043", cat: "politik", topic: "Wahlrecht", type: "flashcard", emoji: "🏅", level: 2,
    term: "Grundmandatsklausel",
    def: "Gewinnt eine Partei mindestens drei Wahlkreise direkt, zieht sie mit ihrem vollen Zweitstimmenanteil in den Bundestag ein – auch unter 5 %.",
    example: "2021: Die Linke kam mit 4,9 % und drei Direktmandaten auf 39 Sitze statt nur 3." },
  { id: "pde-044", cat: "politik", topic: "Wahlrecht", type: "fact", emoji: "✂️", level: 3,
    title: "Wahlrechtsreform 2023: Zweitstimmendeckung",
    text: "Seit 2025 gibt es keine Überhang- und Ausgleichsmandate mehr. Ein Wahlkreissieger erhält seinen Sitz nur, wenn er durch das Zweitstimmenergebnis seiner Partei im Land gedeckt ist.",
    more: "Gewinnt eine Partei in einem Land mehr Wahlkreise, als ihr nach Zweitstimmen Sitze zustehen, gehen die Kandidaten mit den schwächsten Erststimmenergebnissen leer aus. 2025 traf das 23 Wahlkreissieger. Kritik: Manche Wahlkreise sind nun nicht direkt vertreten. Vorteil: Der Bundestag bleibt bei 630 Sitzen." },
  { id: "pde-045", cat: "politik", topic: "Wahlrecht", type: "event", emoji: "⚖️", level: 3, year: "2024",
    title: "BVerfG: Grundmandatsklausel bleibt vorerst",
    text: "Am 30. Juli 2024 billigte Karlsruhe die Zweitstimmendeckung, erklärte aber die Abschaffung der Grundmandatsklausel für verfassungswidrig. Bis zu einer Neuregelung gilt sie weiter.",
    more: "Hintergrund: Ohne Grundmandatsklausel wäre z. B. die CSU, die nur in Bayern antritt, bei bundesweit unter 5 % trotz Gewinn fast aller bayerischen Wahlkreise ganz aus dem Bundestag geflogen (2021 lag sie bei 5,2 %). Das Gericht sah darin eine unzulässige Benachteiligung." },
  { id: "pde-046", cat: "politik", topic: "Wahlrecht", type: "whatif", emoji: "🏘️", level: 3,
    q: "Was passiert, wenn eine Partei in einem Land mehr Wahlkreise gewinnt, als ihr Sitze zustehen?",
    steps: ["Zweitstimmen ergeben z. B. 20 Sitze", "Partei gewinnt aber 23 Wahlkreise", "3 schwächste Sieger bekommen keinen Sitz", "Früher: Überhang- plus Ausgleichsmandate"],
    text: "Das alte System blähte den Bundestag auf (2021: 736 Sitze), weil Überhangmandate für andere Parteien ausgeglichen wurden. Die Zweitstimmendeckung hält die Größe fix, kostet aber einzelne Wahlkreissieger ihr Mandat." },
  { id: "pde-047", cat: "politik", topic: "Wahlrecht", type: "truefalse", emoji: "🗺️", level: 2,
    q: "Der SSW, die Partei der dänischen Minderheit, ist von der 5-%-Hürde befreit.",
    answer: true,
    explain: "Parteien nationaler Minderheiten sind ausgenommen. 2025 gewann der SSW mit rund 0,2 % bundesweit erneut einen Sitz – gewählt wird er nur in Schleswig-Holstein." },
  { id: "pde-048", cat: "politik", topic: "Wahlrecht", type: "quiz", emoji: "🎂", level: 1,
    q: "Ab welchem Alter darf man bei der Bundestagswahl wählen (Stand 2025)?",
    options: ["16", "17", "18", "21"],
    answer: 2,
    explain: "Bei Bundestagswahlen gilt 18 (Art. 38 GG – eine Senkung bräuchte eine Zweidrittelmehrheit). Bei der Europawahl durften 2024 erstmals 16-Jährige wählen, auch in mehreren Ländern bei Landtags- oder Kommunalwahlen." },
  { id: "pde-049", cat: "politik", topic: "Wahlrecht", type: "fact", emoji: "🧱", level: 2,
    title: "Warum es die 5-%-Hürde gibt",
    text: "Die Sperrklausel soll eine Zersplitterung des Parlaments verhindern und stabile Mehrheiten ermöglichen. Der Preis: Millionen Stimmen können ohne Wirkung bleiben.",
    more: "Weimar hatte keine Hürde: Zeitweise saßen über ein Dutzend Parteien im Reichstag, Regierungen hielten im Schnitt weniger als ein Jahr. Das BVerfG akzeptiert die Hürde für den Bundestag – für die Europawahl kippte es sie dagegen 2011 und 2014, weil dort keine Regierung gebildet wird." },
  { id: "pde-050", cat: "politik", topic: "Wahlrecht", type: "number", emoji: "📊", level: 2,
    value: "82,5 %", label: "Wahlbeteiligung bei der Bundestagswahl 2025",
    text: "Der höchste Wert seit der Wiedervereinigung. 2021 hatte sie bei 76,4 % gelegen.",
    more: "Hohe Mobilisierung nach dem Ampel-Bruch und einem stark polarisierten Wahlkampf (Migration, Wirtschaft). Zum Vergleich: Den Rekord hält 1972 mit 91,1 % – die „Willy-Wahl“ nach dem gescheiterten Misstrauensvotum." },
  { id: "pde-051", cat: "politik", topic: "Wahlrecht", type: "quiz", emoji: "📈", level: 2,
    q: "Welche Partei wurde bei der Bundestagswahl 2025 zweitstärkste Kraft?",
    options: ["SPD", "Grüne", "Die Linke", "AfD"],
    answer: 3,
    explain: "Ergebnis: CDU/CSU 28,5 %, AfD 20,8 %, SPD 16,4 %, Grüne 11,6 %, Linke 8,8 %. Die SPD fuhr ihr schlechtestes Bundestagswahlergebnis ein, die AfD verdoppelte sich gegenüber 2021 (10,4 %) nahezu." },

  // ── Gesetzgebung ──
  { id: "pde-052", cat: "politik", topic: "Gesetzgebung", type: "order", emoji: "📜", level: 1,
    q: "Bringe den Weg eines Regierungsentwurfs in die richtige Reihenfolge.",
    items: ["Kabinett beschließt den Entwurf", "Stellungnahme des Bundesrats", "Drei Lesungen im Bundestag", "Zweiter Durchgang im Bundesrat", "Ausfertigung durch den Bundespräsidenten"],
    explain: "Regierungsentwürfe gehen zuerst an den Bundesrat (sechs Wochen Stellungnahme), dann in den Bundestag. Nach dem Bundestagsbeschluss befasst sich der Bundesrat erneut. Zum Schluss unterzeichnet der Präsident, das Gesetz wird im Bundesgesetzblatt verkündet." },
  { id: "pde-053", cat: "politik", topic: "Gesetzgebung", type: "quiz", emoji: "💡", level: 1,
    q: "Wer darf im Bund KEINE Gesetzentwürfe einbringen?",
    options: ["Die Bundesregierung", "Der Bundespräsident", "Der Bundesrat", "Eine Fraktion des Bundestags"],
    answer: 1,
    explain: "Initiativrecht haben Bundesregierung, Bundesrat und „die Mitte des Bundestags“ (eine Fraktion oder 5 % der Abgeordneten). In der Praxis stammen die meisten Gesetze von der Regierung, weil die Ministerien das Fachwissen haben." },
  { id: "pde-054", cat: "politik", topic: "Gesetzgebung", type: "flashcard", emoji: "🔐", level: 1,
    term: "Zustimmungsgesetz",
    def: "Gesetz, das nur mit ausdrücklicher Zustimmung des Bundesrats zustande kommt – etwa wenn es Länderfinanzen, Länderverwaltung oder das Grundgesetz betrifft. Der Bundesrat hat hier ein absolutes Veto.",
    example: "Beispiele: Steuern, deren Aufkommen den Ländern zusteht; Grundgesetzänderungen." },
  { id: "pde-055", cat: "politik", topic: "Gesetzgebung", type: "flashcard", emoji: "✋", level: 2,
    term: "Einspruchsgesetz",
    def: "Regelfall: Der Bundesrat kann nach Anrufung des Vermittlungsausschusses Einspruch einlegen, den der Bundestag aber überstimmen kann – mit absoluter Mehrheit bzw. bei Zweidrittel-Einspruch mit Zweidrittelmehrheit.",
    example: "Der Bundesrat kann hier nur verzögern, nicht endgültig verhindern." },
  { id: "pde-056", cat: "politik", topic: "Gesetzgebung", type: "whatif", emoji: "🛑", level: 2,
    q: "Was passiert, wenn der Bundesrat ein Zustimmungsgesetz ablehnt?",
    steps: ["Gesetz ist zunächst gescheitert", "Bundestag oder Regierung ruft Vermittlung an", "Vermittlungsausschuss sucht Kompromiss", "Ohne Zustimmung: Gesetz endgültig tot"],
    text: "Bei Zustimmungsgesetzen gibt es kein Überstimmen. Deshalb verhandeln Bundesregierungen oft vorab mit den Ländern, etwa mit Geld für Länderhaushalte. Beispiel: Das Bürgergeld kam 2022 erst nach Vermittlungsverfahren mit Änderungen zustande." },
  { id: "pde-057", cat: "politik", topic: "Gesetzgebung", type: "whatif", emoji: "↩️", level: 3,
    q: "Was passiert, wenn der Bundesrat gegen ein Einspruchsgesetz Einspruch einlegt?",
    steps: ["Vermittlungsausschuss war erfolglos", "Bundesrat legt Einspruch ein", "Bundestag stimmt erneut ab", "Mit Kanzlermehrheit: Einspruch überstimmt"],
    text: "Hat der Bundesrat mit absoluter Mehrheit Einspruch eingelegt, reicht im Bundestag die absolute Mehrheit seiner Mitglieder (316). Bei einem Einspruch mit Zweidrittelmehrheit braucht der Bundestag zwei Drittel der abgegebenen Stimmen." },
  { id: "pde-058", cat: "politik", topic: "Gesetzgebung", type: "number", emoji: "🤝", level: 3,
    value: "32", label: "Mitglieder des Vermittlungsausschusses",
    text: "16 Abgeordnete des Bundestags und je ein Vertreter der 16 Länder. Er tagt vertraulich und soll Kompromisse zwischen Bundestag und Bundesrat finden.",
    more: "Die Länder-Mitglieder sind nicht an Weisungen gebunden – das soll echtes Verhandeln ermöglichen. Der Ausschuss darf nur Änderungen vorschlagen, keine eigenen Gesetze schreiben; Bundestag und Bundesrat müssen danach noch zustimmen." },
  { id: "pde-059", cat: "politik", topic: "Gesetzgebung", type: "truefalse", emoji: "📖", level: 1,
    q: "Ein Gesetz gilt sofort, wenn der Bundestag es beschlossen hat.",
    answer: false,
    explain: "Danach kommen noch Bundesrat, Gegenzeichnung durch Kanzler bzw. Minister, Ausfertigung durch den Bundespräsidenten und Verkündung im Bundesgesetzblatt – seit 2023 rein digital. Erst dann kann es in Kraft treten." },
  { id: "pde-060", cat: "politik", topic: "Gesetzgebung", type: "quiz", emoji: "📑", level: 1,
    q: "Wie oft wird ein Gesetzentwurf im Bundestag in der Regel beraten?",
    options: ["In drei Lesungen", "In einer Lesung", "In zwei Lesungen", "So oft der Präsident es will"],
    answer: 0,
    explain: "1. Lesung: Grundsatzdebatte und Überweisung in die Ausschüsse, wo die eigentliche Detailarbeit passiert. 2. Lesung: Änderungsanträge. 3. Lesung: Schlussabstimmung." },

  // ── Föderalismus ──
  { id: "pde-061", cat: "politik", topic: "Föderalismus", type: "fact", emoji: "🗺️", level: 1,
    title: "16 Länder – eigene Staaten im Bundesstaat",
    text: "Die Länder haben eigene Verfassungen, Parlamente, Regierungen und Gerichte. Drei davon sind Stadtstaaten: Berlin, Hamburg und Bremen. Die Länder führen auch die meisten Bundesgesetze aus.",
    more: "Föderalismus war auch ein Wunsch der Alliierten: Macht verteilen, damit nie wieder eine Zentrale alles kontrolliert. Vorteil: Nähe, Wettbewerb um gute Lösungen. Nachteil: Langsame Abstimmung, Flickenteppich – sichtbar etwa in der Corona-Pandemie oder bei Schulabschlüssen." },
  { id: "pde-062", cat: "politik", topic: "Föderalismus", type: "quiz", emoji: "🎓", level: 1,
    q: "Wer ist in Deutschland hauptsächlich für Schulen zuständig?",
    options: ["Der Bund", "Die EU", "Die Länder", "Die Kirchen"],
    answer: 2,
    explain: "Bildung ist Kern der „Kulturhoheit der Länder“. Darum gibt es 16 Schulsysteme. Die Kultusministerkonferenz (KMK) koordiniert, etwa bei gemeinsamen Abiturstandards." },
  { id: "pde-063", cat: "politik", topic: "Föderalismus", type: "flashcard", emoji: "📚", level: 2,
    term: "Kooperationsverbot",
    def: "Mit der Föderalismusreform 2006 durfte der Bund Schulen nicht mehr direkt mitfinanzieren. 2019 wurde es gelockert (Art. 104c GG), damit der Bund z. B. den Digitalpakt Schule bezahlen kann.",
    example: "Digitalpakt: 5 Mrd. € Bundesgeld für WLAN und Tablets an Schulen." },
  { id: "pde-064", cat: "politik", topic: "Föderalismus", type: "quiz", emoji: "🪖", level: 2,
    q: "Was gehört zur ausschließlichen Gesetzgebung des Bundes?",
    options: ["Polizeirecht", "Schulrecht", "Rundfunk", "Verteidigung und Auswärtiges"],
    answer: 3,
    explain: "Art. 73 nennt u. a. Verteidigung, Auswärtiges, Staatsangehörigkeit, Währung und Zölle. Polizei, Schule und Rundfunk sind Ländersache. Grundregel (Art. 30/70): Zuständig sind die Länder, solange das GG nichts anderes sagt." },
  { id: "pde-065", cat: "politik", topic: "Föderalismus", type: "flashcard", emoji: "⚖️", level: 3,
    term: "Konkurrierende Gesetzgebung",
    def: "Die Länder dürfen regeln, solange und soweit der Bund nicht selbst ein Gesetz erlassen hat (Art. 72/74). In der Praxis hat der Bund die meisten dieser Felder besetzt, etwa Zivil-, Straf- und Arbeitsrecht.",
    example: "Seit 2006 dürfen Länder in manchen Feldern abweichen, z. B. bei Jagd oder Naturschutz (Abweichungsgesetzgebung)." },
  { id: "pde-066", cat: "politik", topic: "Föderalismus", type: "fact", emoji: "💶", level: 2,
    title: "Länderfinanzausgleich: Solidarität zwischen Ländern",
    text: "Finanzstarke Länder geben ab, finanzschwache erhalten Mittel, damit überall gleichwertige Lebensverhältnisse möglich sind. Seit 2020 läuft der Ausgleich über die Verteilung der Umsatzsteuer, ergänzt durch Bundesmittel.",
    more: "Volumen zuletzt knapp 19 Mrd. € pro Jahr (2024). Bayern zahlt allein gut die Hälfte, Berlin ist größter Empfänger. Kritik der Zahler: Der Anreiz, eigene Steuerkraft zu steigern, sinkt. Bayern klagt deshalb seit 2023 erneut in Karlsruhe." },
  { id: "pde-067", cat: "politik", topic: "Föderalismus", type: "truefalse", emoji: "🥨", level: 1,
    q: "Bayern war schon immer Geberland im Länderfinanzausgleich.",
    answer: false,
    explain: "Bayern war bis Ende der 1980er-Jahre jahrzehntelang Nehmerland – ein agrarisch geprägtes Land, das vom Ausgleich profitierte. Erst mit dem wirtschaftlichen Aufstieg wurde es zum größten Zahler." },
  { id: "pde-068", cat: "politik", topic: "Föderalismus", type: "number", emoji: "🏘️", level: 2,
    value: "≈ 10.700", label: "Gemeinden in Deutschland",
    text: "Kommunen sind die dritte Ebene: Sie organisieren Kitas, Müllabfuhr, Bauleitplanung, ÖPNV und viel von Integration und Sozialhilfe. Art. 28 GG garantiert ihre Selbstverwaltung.",
    more: "Problem „Konnexität“: Bund und Länder beschließen Aufgaben (z. B. Kita-Rechtsanspruch), die Kommunen müssen sie umsetzen und oft mitbezahlen. Viele Kommunen sind daher hoch verschuldet, der Investitionsstau wird auf rund 200 Mrd. € geschätzt (KfW-Kommunalpanel, Stand 2025)." },
  { id: "pde-069", cat: "politik", topic: "Föderalismus", type: "whatif", emoji: "🧩", level: 2,
    q: "Was passiert, wenn der Bund ein Gesetz beschließt, das die Länder ausführen müssen?",
    steps: ["Länderbehörden setzen es um", "Länder tragen Verwaltungskosten", "Oft Zustimmung des Bundesrats nötig", "Länder handeln Geld vom Bund aus"],
    text: "Deutschland hat einen Vollzugsföderalismus: Der Bund macht viele Gesetze, die Länder führen sie aus. Daraus folgt die starke Rolle des Bundesrats und das ständige Ringen ums Geld zwischen den Ebenen." },

  // ── Parteien ──
  { id: "pde-070", cat: "politik", topic: "Parteien", type: "fact", emoji: "🎪", level: 1,
    title: "Parteien im Grundgesetz",
    text: "Art. 21 gibt Parteien eine Verfassungsrolle: Sie wirken bei der politischen Willensbildung mit. Ihre innere Ordnung muss demokratisch sein, und sie müssen offenlegen, woher ihr Geld kommt.",
    more: "Das ist ungewöhnlich: Viele Verfassungen erwähnen Parteien gar nicht. Das GG adelt sie als Mittler zwischen Bürgern und Staat – und unterwirft sie zugleich Regeln. Kritiker sprechen deshalb manchmal vom „Parteienstaat“." },
  { id: "pde-071", cat: "politik", topic: "Parteien", type: "order", emoji: "📅", level: 2,
    q: "Ordne die Gründung dieser Parteien chronologisch.",
    items: ["SPD (Vorläufer ADAV)", "CDU", "Die Grünen", "AfD", "BSW"],
    explain: "SPD-Vorläufer ADAV 1863 – älteste Partei Deutschlands. CDU 1945, Grüne 1980 (im Bundestag seit 1983), AfD 2013 (zunächst eurokritisch), Bündnis Sahra Wagenknecht 2024." },
  { id: "pde-072", cat: "politik", topic: "Parteien", type: "quiz", emoji: "🦁", level: 1,
    q: "Was ist die Besonderheit der CSU?",
    options: ["Sie tritt nur in Bayern an", "Sie ist keine eigene Partei", "Sie ist von der 5-%-Hürde befreit", "Sie stellte nie einen Minister"],
    answer: 0,
    explain: "Die CSU tritt nur in Bayern an, die CDU in allen anderen Ländern. Im Bundestag bilden sie eine gemeinsame Fraktion. Dennoch ist die CSU eigenständig – mit eigenem Programm und eigenen Ministern." },
  { id: "pde-073", cat: "politik", topic: "Parteien", type: "fact", emoji: "💰", level: 2,
    title: "Wie sich Parteien finanzieren",
    text: "Mitgliedsbeiträge, Spenden, Mandatsträgerabgaben – und staatliche Teilfinanzierung: Geld gibt es pro erhaltener Wählerstimme und als Zuschuss auf Beiträge und Kleinspenden.",
    more: "Anspruch hat, wer mindestens 0,5 % bei Bundestags- oder Europawahl bzw. 1 % bei einer Landtagswahl holt. Grenzen: Staatsgeld darf die selbst erwirtschafteten Einnahmen nicht übersteigen (relative Obergrenze), dazu kommt eine jährliche absolute Obergrenze für alle Parteien zusammen. Ziel: Parteien sollen in der Gesellschaft verwurzelt bleiben." },
  { id: "pde-074", cat: "politik", topic: "Parteien", type: "number", emoji: "🔎", level: 3,
    value: "35.000 €", label: "Ab hier müssen Spenden sofort gemeldet werden",
    text: "Großspenden ab 35.000 € müssen unverzüglich dem Bundestagspräsidenten angezeigt und veröffentlicht werden (seit 2024, vorher 50.000 €). Ab 10.000 € erscheinen Spender namentlich im jährlichen Rechenschaftsbericht.",
    more: "Hintergrund sind Skandale wie die CDU-Spendenaffäre um 1999/2000 (schwarze Kassen unter Kohl). Kritiker bemängeln, dass Sponsoring (z. B. Stände auf Parteitagen) lange weniger transparent war als Spenden." },
  { id: "pde-075", cat: "politik", topic: "Parteien", type: "quiz", emoji: "🚫", level: 2,
    q: "Wer darf über das Verbot einer Partei entscheiden?",
    options: ["Der Bundestag mit Zweidrittelmehrheit", "Das Bundesinnenministerium", "Nur das Bundesverfassungsgericht", "Der Verfassungsschutz"],
    answer: 2,
    explain: "Das „Parteienprivileg“: Nur das BVerfG darf eine Partei verbieten, mit Zweidrittelmehrheit des Senats. Antrag stellen können Bundestag, Bundesrat oder Bundesregierung. Vereine dagegen kann das Innenministerium verbieten." },
  { id: "pde-076", cat: "politik", topic: "Parteien", type: "truefalse", emoji: "⚖️", level: 2,
    q: "Die NPD wurde 2017 vom Bundesverfassungsgericht verboten.",
    answer: false,
    explain: "Das Gericht stellte zwar fest, dass die NPD verfassungsfeindliche Ziele verfolgt, sah aber keine Chance, dass sie diese erreicht (fehlende „Potentialität“). 2024 wurde die Nachfolgepartei „Die Heimat“ stattdessen für sechs Jahre von der staatlichen Finanzierung ausgeschlossen." },
  { id: "pde-077", cat: "politik", topic: "Parteien", type: "number", emoji: "🚷", level: 2,
    value: "2", label: "Parteiverbote in der Geschichte der Bundesrepublik",
    text: "1952 die neonazistische Sozialistische Reichspartei (SRP), 1956 die KPD. Seitdem scheiterten Verbotsanträge gegen die NPD 2003 (V-Leute-Problematik) und 2017.",
    more: "Die Hürden sind bewusst hoch: Eine Partei muss aktiv-kämpferisch gegen die freiheitliche demokratische Grundordnung vorgehen und ihre Ziele realistischerweise erreichen können. Ein Verbot greift tief in den demokratischen Wettbewerb ein." },
  { id: "pde-078", cat: "politik", topic: "Parteien", type: "whatif", emoji: "⛔", level: 3,
    q: "Was passiert, wenn das BVerfG eine Partei verbietet?",
    steps: ["Partei wird aufgelöst", "Vermögen kann eingezogen werden", "Ersatzorganisationen sind verboten", "Ihre Abgeordneten verlieren ihr Mandat"],
    text: "So geschehen 1952 bei der SRP: Ihre Mandate in Bund und Ländern erloschen. Seit 2017 gibt es zudem die mildere Stufe: Ausschluss von der staatlichen Parteienfinanzierung für verfassungsfeindliche Parteien." },
  { id: "pde-079", cat: "politik", topic: "Parteien", type: "fact", emoji: "🔭", level: 3,
    title: "Verfassungsschutz und AfD (Stand Mitte 2025)",
    text: "Im Mai 2025 stufte das Bundesamt für Verfassungsschutz die AfD bundesweit als „gesichert rechtsextremistisch“ ein. Die AfD klagte; bis zur Gerichtsentscheidung setzt das Amt die Einstufung aus.",
    more: "Wichtig zur Einordnung: Die Einstufung erlaubt mehr nachrichtendienstliche Beobachtung, ist aber kein Verbot – das kann nur das BVerfG aussprechen. Ob ein Verbotsantrag gestellt werden soll, ist politisch umstritten; Befürworter verweisen auf die wehrhafte Demokratie, Gegner auf Risiken und demokratischen Wettbewerb." },
  // ── Koalitionen & Regierungen ──
  { id: "pde-080", cat: "politik", topic: "Regierungen", type: "number", emoji: "👔", level: 1,
    value: "10", label: "Bundeskanzler seit 1949",
    text: "Adenauer, Erhard, Kiesinger, Brandt, Schmidt, Kohl, Schröder, Merkel, Scholz und Merz. Sechs von der CDU, vier von der SPD.",
    more: "Merkhilfe für die lange Linie: „Adenauer baute auf, Brandt öffnete nach Osten, Kohl vereinte, Merkel moderierte Krisen.“ Die längsten Amtszeiten: Kohl und Merkel mit je 16 Jahren, Adenauer mit 14. Die kürzeste: Kiesinger mit knapp drei Jahren." },
  { id: "pde-081", cat: "politik", topic: "Regierungen", type: "order", emoji: "🕰️", level: 1,
    q: "Ordne diese Bundeskanzler nach Amtsantritt.",
    items: ["Konrad Adenauer", "Willy Brandt", "Helmut Kohl", "Angela Merkel", "Friedrich Merz"],
    explain: "Adenauer 1949, Brandt 1969, Kohl 1982, Merkel 2005, Merz 2025. Dazwischen u. a. Erhard (1963), Kiesinger (1966), Schmidt (1974), Schröder (1998) und Scholz (2021)." },
  { id: "pde-082", cat: "politik", topic: "Regierungen", type: "quiz", emoji: "🤝", level: 2,
    q: "Unter welchem Kanzler regierte die erste Große Koalition aus Union und SPD?",
    options: ["Konrad Adenauer", "Ludwig Erhard", "Helmut Schmidt", "Kurt Georg Kiesinger"],
    answer: 3,
    explain: "1966–1969 unter Kiesinger (CDU), Vizekanzler war Willy Brandt (SPD). Sie beschloss u. a. die umstrittenen Notstandsgesetze. Weitere Große Koalitionen gab es unter Merkel (2005–09, 2013–21)." },
  { id: "pde-083", cat: "politik", topic: "Regierungen", type: "truefalse", emoji: "🥇", level: 2,
    q: "Den Kanzler stellt immer die Partei, die bei der Wahl stärkste Kraft wurde.",
    answer: false,
    explain: "Entscheidend ist eine Mehrheit im Bundestag. 1969 wurde die Union stärkste Kraft, doch Brandt (SPD) bildete mit der FDP die sozialliberale Koalition. Auch Helmut Schmidt regierte 1976 und 1980 als Kanzler der zweitstärksten Partei." },
  { id: "pde-084", cat: "politik", topic: "Regierungen", type: "event", emoji: "💥", level: 1, year: "2024",
    title: "Ampel-Aus: Scholz entlässt Lindner",
    text: "Am 6. November 2024 entließ Kanzler Scholz Finanzminister Christian Lindner (FDP). Streitpunkt war vor allem der Haushalt 2025 und die Schuldenbremse. Die FDP verließ die Regierung, Rot-Grün regierte als Minderheit weiter.",
    more: "Die Ampel war die erste Bundeskoalition aus SPD, Grünen und FDP (seit Dezember 2021). Spannung von Beginn an: Grüne und SPD wollten mehr investieren, die FDP an der Schuldenbremse festhalten – das Karlsruher Haushaltsurteil 2023 verschärfte den Konflikt massiv." },
  { id: "pde-085", cat: "politik", topic: "Regierungen", type: "order", emoji: "📆", level: 2,
    q: "Bringe die Ereignisse vom Ampel-Bruch bis zur Regierung Merz in die Reihenfolge.",
    items: ["Entlassung Lindners (Nov. 2024)", "Verlorene Vertrauensfrage (Dez. 2024)", "Auflösung des Bundestags durch Steinmeier", "Bundestagswahl am 23. Februar 2025", "Wahl von Friedrich Merz zum Kanzler (Mai 2025)"],
    explain: "Scholz verlor die Vertrauensfrage am 16.12.2024, Steinmeier löste den Bundestag am 27.12. auf. Nach der Wahl im Februar wurde Merz am 6. Mai 2025 gewählt." },
  { id: "pde-086", cat: "politik", topic: "Regierungen", type: "event", emoji: "🗳️", level: 2, year: "2025",
    title: "Merz scheitert im ersten Wahlgang",
    text: "Am 6. Mai 2025 verfehlte Friedrich Merz im ersten Wahlgang die Kanzlermehrheit (310 statt 316 Stimmen) – ein Novum in der Geschichte der Bundesrepublik. Im zweiten Wahlgang am selben Tag wurde er mit 325 Stimmen gewählt.",
    more: "Union und SPD hatten zusammen 328 Sitze, also nur eine knappe Mehrheit. Die geheime Wahl zeigte: Einige Koalitionsabgeordnete verweigerten die Stimme. Der schnelle zweite Wahlgang am selben Tag erforderte eine Fristverkürzung mit Zweidrittelmehrheit – dafür stimmten auch Grüne und Linke." },
  { id: "pde-087", cat: "politik", topic: "Regierungen", type: "quiz", emoji: "💼", level: 1,
    q: "Wer ist in der Regierung Merz Vizekanzler und Finanzminister?",
    options: ["Boris Pistorius", "Lars Klingbeil", "Alexander Dobrindt", "Johann Wadephul"],
    answer: 1,
    explain: "Lars Klingbeil (SPD) ist Vizekanzler und Finanzminister. Pistorius (SPD) blieb Verteidigungsminister, Dobrindt (CSU) wurde Innen-, Wadephul (CDU) Außenminister. Stand 2025." },
  { id: "pde-088", cat: "politik", topic: "Regierungen", type: "flashcard", emoji: "📝", level: 1,
    term: "Koalitionsvertrag",
    def: "Politische Vereinbarung der Regierungsparteien über Vorhaben, Ressortverteilung und Konfliktregeln. Rechtlich nicht einklagbar, aber politisch bindend. Streit wird im Koalitionsausschuss geklärt.",
    example: "Schwarz-Rot 2025: „Verantwortung für Deutschland“; die SPD-Mitglieder stimmten mit rund 85 % zu." },
  { id: "pde-089", cat: "politik", topic: "Regierungen", type: "whatif", emoji: "🧮", level: 3,
    q: "Was passiert, wenn kein Kandidat die Kanzlermehrheit erreicht?",
    steps: ["Bundestag hat 14 Tage für eigene Kandidaten", "Danach: relative Mehrheit genügt", "Präsident ernennt oder löst auf", "Option: Minderheitsregierung"],
    text: "Art. 63: Erhält der Gewählte im dritten Wahlgang nur eine relative Mehrheit, entscheidet der Bundespräsident binnen sieben Tagen, ob er ihn ernennt oder den Bundestag auflöst. Auf Bundesebene ist das noch nie vorgekommen." },
  { id: "pde-090", cat: "politik", topic: "Regierungen", type: "truefalse", emoji: "⏳", level: 3,
    q: "Nach einer Bundestagswahl ist das Land bis zur Wahl des neuen Kanzlers ohne Regierung.",
    answer: false,
    explain: "Mit dem Zusammentritt des neuen Bundestags endet zwar das Amt von Kanzler und Ministern, doch auf Ersuchen des Bundespräsidenten führen sie die Geschäfte weiter (Art. 69 Abs. 3) – als geschäftsführende Regierung." },
  { id: "pde-091", cat: "politik", topic: "Regierungen", type: "quiz", emoji: "🌹", level: 1,
    q: "Wer war der erste SPD-Bundeskanzler?",
    options: ["Helmut Schmidt", "Gerhard Schröder", "Willy Brandt", "Kurt Schumacher"],
    answer: 2,
    explain: "Willy Brandt wurde 1969 Kanzler – 20 Jahre nach Gründung der Bundesrepublik. Kurt Schumacher führte die SPD nach dem Krieg, wurde aber nie Kanzler; die frühen Jahre prägte die Union unter Adenauer." },

  // ── Staatsfinanzen ──
  { id: "pde-092", cat: "politik", topic: "Staatsfinanzen", type: "fact", emoji: "🧱", level: 1,
    title: "Die Schuldenbremse",
    text: "Seit 2009 im Grundgesetz (Art. 109, 115): Der Bund darf strukturell nur Kredite von maximal 0,35 % des BIP aufnehmen, die Länder seit 2020 gar keine. In Rezessionen und Notlagen sind Ausnahmen erlaubt.",
    more: "Eingeführt nach der Finanzkrise, um die Schuldenquote zu senken. Befürworter: Generationengerechtigkeit, Zinslast begrenzen. Kritiker: Sie bremst Investitionen in Schienen, Brücken, Schulen. Der Streit darüber sprengte 2024 die Ampel und prägte 2025 die Reform." },
  { id: "pde-093", cat: "politik", topic: "Staatsfinanzen", type: "number", emoji: "📏", level: 3,
    value: "0,35 %", label: "des BIP: strukturelle Neuverschuldung des Bundes",
    text: "Bei rund 4,3 Billionen € BIP entspricht das etwa 15 Mrd. € pro Jahr. Dazu kommt eine Konjunkturkomponente: In schlechten Zeiten darf mehr geliehen werden, in guten weniger.",
    more: "„Strukturell“ heißt: um Konjunktureffekte bereinigt. Logik dahinter: Der Staat soll in der Krise stützen (automatische Stabilisatoren), aber über den Zyklus hinweg keine dauerhaften Defizite fahren." },
  { id: "pde-094", cat: "politik", topic: "Staatsfinanzen", type: "whatif", emoji: "🚨", level: 2,
    q: "Was passiert, wenn der Bundestag eine Notlage für die Schuldenbremse erklärt?",
    steps: ["Beschluss mit Kanzlermehrheit", "Zusätzliche Kredite werden erlaubt", "Tilgungsplan wird Pflicht", "Kredite müssen der Notlage dienen"],
    text: "So geschehen 2020–2022 (Corona, Energiekrise). Das BVerfG-Urteil 2023 stellte klar: Notlagenkredite dürfen nicht für spätere Jahre „geparkt“ oder für andere Zwecke umgewidmet werden." },
  { id: "pde-095", cat: "politik", topic: "Staatsfinanzen", type: "event", emoji: "🏗️", level: 1, year: "2025",
    title: "Grundgesetzänderung zur Finanzierung von Verteidigung und Infrastruktur",
    text: "Im März 2025 änderten Bundestag und Bundesrat das GG: Verteidigungsausgaben über 1 % des BIP sind von der Schuldenbremse ausgenommen, und ein kreditfinanziertes Sondervermögen Infrastruktur von 500 Mrd. € über 12 Jahre wurde geschaffen.",
    more: "Davon gehen 100 Mrd. € an die Länder und 100 Mrd. € in den Klima- und Transformationsfonds – Letzteres war Bedingung der Grünen für ihre Zustimmung. Außerdem dürfen nun auch die Länder strukturell Kredite von 0,35 % des BIP aufnehmen. Es war die größte Lockerung der Schuldenregeln seit 2009." },
  { id: "pde-096", cat: "politik", topic: "Staatsfinanzen", type: "whatif", emoji: "🔑", level: 3,
    q: "Was passiert, wenn im neuen Bundestag AfD und Linke zusammen über ein Drittel der Sitze haben?",
    steps: ["Sie bilden eine Sperrminorität", "GG-Änderungen brauchen ihre Stimmen", "Union und SPD nutzen den alten Bundestag", "Reform im März 2025 vor Konstituierung"],
    text: "AfD (152) und Linke (64) kamen zusammen auf 216 von 630 Sitzen – mehr als ein Drittel. Deshalb ließen Union und SPD die Schuldenbremsen-Reform noch vom alten Bundestag beschließen. Eilanträge dagegen scheiterten in Karlsruhe." },
  { id: "pde-097", cat: "politik", topic: "Staatsfinanzen", type: "number", emoji: "💶", level: 1,
    value: "≈ 500 Mrd. €", label: "Ausgaben im Bundeshaushalt 2025",
    text: "Der größte Einzelposten ist der Etat für Arbeit und Soziales mit rund 190 Mrd. € – mehr als ein Drittel. Ein großer Teil davon sind Zuschüsse an die Rentenversicherung.",
    more: "Hinzu kommen kreditfinanzierte Sondervermögen außerhalb des Kernhaushalts. Der Haushalt 2025 wurde wegen der Neuwahl erst im September 2025 beschlossen; bis dahin galt die vorläufige Haushaltsführung (nur rechtlich gebotene Ausgaben)." },
  { id: "pde-098", cat: "politik", topic: "Staatsfinanzen", type: "quiz", emoji: "🧾", level: 2,
    q: "Welche Einzelsteuer bringt dem deutschen Staat am meisten ein?",
    options: ["Körperschaftsteuer", "Energiesteuer", "Umsatzsteuer (Mehrwertsteuer)", "Erbschaftsteuer"],
    answer: 2,
    explain: "Die Umsatzsteuer bringt rund 300 Mrd. € im Jahr, knapp vor der Lohnsteuer. Zusammen mit veranlagter Einkommensteuer sind die Steuern auf Einkommen aber ähnlich gewichtig. Insgesamt nahm der Staat 2024 knapp 950 Mrd. € Steuern ein." },
  { id: "pde-099", cat: "politik", topic: "Staatsfinanzen", type: "flashcard", emoji: "🧺", level: 3,
    term: "Gemeinschaftsteuern",
    def: "Steuern, deren Aufkommen sich Bund, Länder und teils Gemeinden teilen: Einkommen-, Körperschaft- und Umsatzsteuer. Sie machen rund drei Viertel aller Steuereinnahmen aus.",
    example: "Daneben gibt es reine Bundessteuern (z. B. Energiesteuer), Ländersteuern (Grunderwerbsteuer) und Gemeindesteuern (Gewerbe-, Grundsteuer)." },
  { id: "pde-100", cat: "politik", topic: "Staatsfinanzen", type: "flashcard", emoji: "🗃️", level: 2,
    term: "Sondervermögen",
    def: "Vom Kernhaushalt getrennter Topf für einen bestimmten Zweck, oft kreditfinanziert. Eigentlich „Sonderschulden“: Wird er im Grundgesetz verankert, gilt die Schuldenbremse dafür nicht.",
    example: "Sondervermögen Bundeswehr (100 Mrd. €, 2022), Sondervermögen Infrastruktur und Klimaneutralität (500 Mrd. €, 2025)." },
  { id: "pde-101", cat: "politik", topic: "Staatsfinanzen", type: "truefalse", emoji: "🇪🇺", level: 1,
    q: "Deutschlands Staatsschuldenquote liegt deutlich über dem Durchschnitt der Eurozone.",
    answer: false,
    explain: "Mit gut 62 % des BIP (2024) liegt Deutschland klar unter dem Eurozonen-Schnitt von fast 90 % und knapp über der Maastricht-Grenze von 60 %. Italien liegt bei über 130 %, Frankreich bei über 110 %." },
  { id: "pde-102", cat: "politik", topic: "Staatsfinanzen", type: "quiz", emoji: "📈", level: 3,
    q: "Warum steigt die Bedeutung der Zinsausgaben im Bundeshaushalt wieder?",
    options: ["Weil die EU Strafzinsen verlangt", "Weil alte Niedrigzins-Anleihen durch teurere ersetzt werden und neue Schulden hinzukommen", "Weil der Bund keine Anleihen mehr ausgibt", "Weil die Bundesbank Zinsen erhebt"],
    answer: 1,
    explain: "In der Nullzinsphase verdiente der Bund teils sogar an neuen Schulden. Seit der Zinswende 2022 müssen fällige Anleihen zu höheren Zinsen refinanziert werden – die Zinslast hat sich vervielfacht und engt künftige Haushalte ein." },

  // ── Sozialstaat ──
  { id: "pde-103", cat: "politik", topic: "Sozialstaat", type: "fact", emoji: "🔄", level: 1,
    title: "Rente im Umlageverfahren",
    text: "Die heutigen Beitragszahler finanzieren direkt die heutigen Renten – es wird nichts angespart. Im Gegenzug erwirbt man Rentenpunkte, aus denen sich später der eigene Anspruch ergibt.",
    more: "Das nennt man Generationenvertrag. Vorteil: sofort einsatzbereit, inflationsunabhängig, keine Kapitalmarktrisiken. Nachteil: Abhängig vom Verhältnis Erwerbstätige zu Rentnern. In den 1960er-Jahren kamen auf einen Rentner etwa sechs Beitragszahler, heute nur noch rund zwei." },
  { id: "pde-104", cat: "politik", topic: "Sozialstaat", type: "whatif", emoji: "👴", level: 1,
    q: "Was passiert, wenn die Babyboomer in Rente gehen?",
    steps: ["Mehr Rentner, weniger Beitragszahler", "Rentenkasse gerät unter Druck", "Beiträge steigen oder Rentenniveau sinkt", "Oder: höhere Steuerzuschüsse"],
    text: "Die geburtenstarken Jahrgänge 1955–1969 gehen bis Mitte der 2030er in Rente. Politische Stellschrauben: Beitragssatz, Rentenniveau, Renteneintrittsalter, Steuerzuschuss – oder mehr Erwerbstätige durch Zuwanderung und höhere Frauenerwerbsquote." },
  { id: "pde-105", cat: "politik", topic: "Sozialstaat", type: "number", emoji: "📊", level: 1,
    value: "48 %", label: "Haltelinie für das Rentenniveau",
    text: "Das Rentenniveau beschreibt das Verhältnis einer Standardrente (45 Jahre Durchschnittsverdienst) zum Durchschnittslohn, vor Steuern. Die Koalition aus Union und SPD hat vereinbart, die 48 % bis 2031 zu sichern.",
    more: "Wichtig: 48 % heißt NICHT, dass jeder 48 % seines letzten Gehalts bekommt. Es ist eine statistische Kennzahl. Wer weniger Jahre oder unterdurchschnittlich verdient hat, liegt darunter. Die Haltelinie kostet Milliarden, weil sie die demografisch bedingte Absenkung stoppt." },
  { id: "pde-106", cat: "politik", topic: "Sozialstaat", type: "number", emoji: "💸", level: 2,
    value: "18,6 %", label: "Beitragssatz zur Rentenversicherung (seit 2018)",
    text: "Je zur Hälfte von Arbeitgeber und Arbeitnehmer gezahlt. Zusammen mit Kranken-, Pflege- und Arbeitslosenversicherung liegen die Sozialabgaben bei über 40 % des Bruttolohns.",
    more: "Die 40-%-Marke gilt als politische Schmerzgrenze, weil hohe Lohnnebenkosten Arbeit verteuern. Prognosen erwarten bis 2030 einen deutlichen Anstieg des Rentenbeitrags über 20 %, wenn das Rentenniveau gehalten wird (Stand 2025)." },
  { id: "pde-107", cat: "politik", topic: "Sozialstaat", type: "truefalse", emoji: "🏦", level: 1,
    q: "Die Beiträge zur gesetzlichen Rente werden auf einem persönlichen Konto für mich angelegt.",
    answer: false,
    explain: "Im Umlageverfahren fließen die Beiträge sofort an heutige Rentner. Man sammelt nur Ansprüche (Entgeltpunkte). Kapitalgedeckt sind dagegen Riester, Betriebsrenten oder die private Vorsorge." },
  { id: "pde-108", cat: "politik", topic: "Sozialstaat", type: "number", emoji: "🏛️", level: 3,
    value: "> 110 Mrd. €", label: "Steuerzuschüsse des Bundes zur Rente pro Jahr",
    text: "Fast ein Viertel des Bundeshaushalts fließt in die Rentenversicherung (Stand 2025). Offiziell bezahlt der Bund damit „versicherungsfremde Leistungen“ wie Mütterrente oder Renten für Zeiten ohne Beiträge.",
    more: "Faktisch ist die Rente damit teils steuerfinanziert: Etwa ein Viertel ihrer Einnahmen stammt vom Bund. Jede Rentenreform hat daher direkte Folgen für Haushalt und Schuldenbremse – ein Kernkonflikt jeder Koalition." },
  { id: "pde-109", cat: "politik", topic: "Sozialstaat", type: "order", emoji: "🏥", level: 2,
    q: "Ordne die Einführung der fünf Säulen der Sozialversicherung.",
    items: ["Krankenversicherung", "Unfallversicherung", "Rentenversicherung", "Arbeitslosenversicherung", "Pflegeversicherung"],
    explain: "Unter Bismarck: Kranken (1883), Unfall (1884), Invaliditäts- und Alterssicherung (1889). Arbeitslosenversicherung 1927 (Weimar), Pflegeversicherung 1995. Bismarck wollte so auch die Arbeiterbewegung schwächen." },
  { id: "pde-110", cat: "politik", topic: "Sozialstaat", type: "flashcard", emoji: "🧾", level: 1,
    term: "Bürgergeld",
    def: "Seit 2023 Grundsicherung für erwerbsfähige Hilfebedürftige (Nachfolger von Hartz IV). Regelsatz für Alleinstehende 563 € im Monat (2024–2026), zusätzlich werden angemessene Miete und Heizung übernommen.",
    example: "Rund 5,5 Mio. Menschen beziehen es (Stand 2025), darunter etwa 1,5 Mio. Kinder. Union und SPD planen einen Umbau zur „Neuen Grundsicherung“ mit strengeren Pflichten." },
  { id: "pde-111", cat: "politik", topic: "Sozialstaat", type: "quiz", emoji: "🎂", level: 2,
    q: "Für wen gilt die Regelaltersgrenze von 67 Jahren voll?",
    options: ["Für alle seit 2012", "Für Jahrgänge ab 1964", "Nur für Beamte", "Für Jahrgänge ab 1950"],
    answer: 1,
    explain: "Seit 2012 steigt die Altersgrenze schrittweise von 65 auf 67. Wer 1964 oder später geboren ist, geht regulär mit 67 – also ab 2031. Mit 45 Beitragsjahren ist ein früherer abschlagsfreier Rentenbeginn möglich." },
  { id: "pde-112", cat: "politik", topic: "Sozialstaat", type: "fact", emoji: "🩺", level: 2,
    title: "Zweiteilung: Gesetzliche und private Krankenversicherung",
    text: "Rund 90 % sind gesetzlich versichert (GKV), etwa 10 % privat (PKV). Die GKV kostet 14,6 % des Bruttolohns plus kassenindividuellen Zusatzbeitrag, die PKV richtet sich nach Alter und Gesundheitsrisiko.",
    more: "Wechseln in die PKV können v. a. Beamte, Selbstständige und Angestellte über der Versicherungspflichtgrenze. In der GKV gilt Solidarität (Beitrag nach Einkommen, Familie beitragsfrei mitversichert), in der PKV Äquivalenz (Prämie nach Risiko, Rückstellungen fürs Alter). Der durchschnittliche Zusatzbeitrag stieg 2025 auf 2,5 %." },
  { id: "pde-113", cat: "politik", topic: "Sozialstaat", type: "truefalse", emoji: "🎓", level: 1,
    q: "Beamte zahlen in die gesetzliche Rentenversicherung ein.",
    answer: false,
    explain: "Beamte erhalten Pensionen direkt aus den Haushalten von Bund, Ländern und Kommunen, ohne eigene Beiträge. Vorschläge, sie in die Rentenversicherung einzubeziehen, kehren regelmäßig wieder – das würde kurzfristig Beiträge bringen, langfristig aber auch Ansprüche." },
  // ── Migration & Asyl ──
  { id: "pde-114", cat: "politik", topic: "Migration", type: "fact", emoji: "🧳", level: 1,
    title: "Drei Wege zum Schutz",
    text: "Asyl nach Art. 16a GG (politische Verfolgung), Flüchtlingsschutz nach der Genfer Flüchtlingskonvention und subsidiärer Schutz (z. B. bei drohender Gefahr durch Bürgerkrieg). Über die Anträge entscheidet das BAMF.",
    more: "Überraschend: Asyl nach Art. 16a wird nur sehr selten gewährt (um 1 % der Entscheidungen), weil er seit dem Asylkompromiss 1993 nicht greift, wer über einen sicheren Drittstaat einreist – also fast jeder auf dem Landweg. Die meisten Schutzberechtigten erhalten Schutz nach GFK oder subsidiären Schutz." },
  { id: "pde-115", cat: "politik", topic: "Migration", type: "event", emoji: "🚉", level: 1, year: "2015",
    title: "Flüchtlingskrise: „Wir schaffen das“",
    text: "Am 31. August 2015 sagte Angela Merkel den Satz, der zum Symbol wurde. Anfang September ließ die Regierung in Ungarn festsitzende Flüchtlinge einreisen. 2015/16 kamen über eine Million Schutzsuchende.",
    more: "Die Entscheidung prägt die Politik bis heute: Sie löste eine Welle der Hilfsbereitschaft aus, aber auch scharfe Kritik und trug zum Aufstieg der AfD bei. Folgen u. a.: EU-Türkei-Abkommen 2016, mehrere Asylrechtsverschärfungen und ein Dauerstreit um Steuerung und Integration." },
  { id: "pde-116", cat: "politik", topic: "Migration", type: "number", emoji: "📈", level: 2,
    value: "≈ 722.000", label: "Asyl-Erstanträge 2016 – bis heute Rekord",
    text: "Viele 2015 Eingereiste stellten ihren Antrag erst 2016. Danach sanken die Zahlen, stiegen 2023 wieder auf rund 330.000 und fielen 2024 auf etwa 230.000 Erstanträge.",
    more: "2025 gingen die Zahlen weiter deutlich zurück. Gründe für Schwankungen: Lage in Herkunftsländern (Syrien, Afghanistan, Türkei), Routen und Grenzkontrollen. Nicht enthalten sind die über eine Million Ukrainer – sie brauchen kein Asylverfahren." },
  { id: "pde-117", cat: "politik", topic: "Migration", type: "quiz", emoji: "🇺🇦", level: 2,
    q: "Welchen Status erhalten Geflüchtete aus der Ukraine in Deutschland?",
    options: ["Asyl nach Art. 16a GG", "Vorübergehenden Schutz nach EU-Richtlinie, ohne Asylverfahren", "Sie gelten als Touristen", "Sie müssen alle ein Asylverfahren durchlaufen"],
    answer: 1,
    explain: "Die EU aktivierte 2022 erstmals die Richtlinie über vorübergehenden Schutz (in Deutschland § 24 AufenthG). Das ersparte Millionen Einzelverfahren und erlaubte sofort Arbeit. Rund 1,2 Mio. Ukrainer leben in Deutschland (Stand 2025)." },
  { id: "pde-118", cat: "politik", topic: "Migration", type: "quiz", emoji: "🇪🇺", level: 2,
    q: "Welcher Staat ist nach der Dublin-Verordnung meist für ein Asylverfahren zuständig?",
    options: ["Der Staat, in dem der Antragsteller erstmals EU-Boden betreten hat", "Immer Deutschland", "Der Staat mit den meisten freien Plätzen", "Der Wunschstaat des Antragstellers"],
    answer: 0,
    explain: "Das belastet Grenzstaaten wie Italien und Griechenland, die viele Ankommende weiterreisen lassen. Überstellungen in den zuständigen Staat scheitern oft an Fristen. Die EU-Asylreform (GEAS) soll ab Juni 2026 u. a. mit Grenzverfahren und Solidaritätsmechanismus gegensteuern." },
  { id: "pde-119", cat: "politik", topic: "Migration", type: "whatif", emoji: "📄", level: 2,
    q: "Was passiert, wenn ein Asylantrag abgelehnt wird?",
    steps: ["Klage vor dem Verwaltungsgericht möglich", "Danach Pflicht zur Ausreise", "Keine Papiere, Krankheit? → Duldung", "Sonst Abschiebung durch die Länder"],
    text: "Eine Duldung ist kein Aufenthaltsrecht, nur eine ausgesetzte Abschiebung. Abschiebungen sind Ländersache und scheitern oft an fehlenden Pässen, Untertauchen oder nicht kooperierenden Herkunftsstaaten. Deshalb setzt die Politik auf Rückführungsabkommen." },
  { id: "pde-120", cat: "politik", topic: "Migration", type: "fact", emoji: "🛂", level: 2,
    title: "Einbürgerung: Reform 2024",
    text: "Seit Juni 2024 ist die Einbürgerung nach 5 statt 8 Jahren möglich, und Mehrstaatigkeit ist generell erlaubt. Voraussetzungen bleiben u. a. Sprachkenntnisse, eigener Lebensunterhalt und Bekenntnis zur Verfassung.",
    more: "Die zusätzlich eingeführte „Turbo-Einbürgerung“ nach 3 Jahren bei besonderen Integrationsleistungen schaffte die Koalition aus Union und SPD 2025 wieder ab. Hintergrund der Reform: Arbeitskräfte halten und die Zahl der dauerhaft hier lebenden Nicht-Staatsbürger verringern." },
  { id: "pde-121", cat: "politik", topic: "Migration", type: "truefalse", emoji: "👷", level: 1,
    q: "Deutschland wirbt mit dem Fachkräfteeinwanderungsgesetz gezielt Arbeitskräfte aus Nicht-EU-Staaten an.",
    answer: true,
    explain: "Seit der Reform 2023 gibt es u. a. die „Chancenkarte“ (Punktesystem zur Jobsuche, seit 2024) und erleichterte Anerkennung. Hintergrund: Demografie – bis Mitte der 2030er scheiden Millionen Babyboomer aus dem Arbeitsmarkt aus." },

  // ── Energie & Klima ──
  { id: "pde-122", cat: "politik", topic: "Energie & Klima", type: "event", emoji: "☢️", level: 1, year: "2023",
    title: "Die letzten drei Atomkraftwerke gehen vom Netz",
    text: "Am 15. April 2023 wurden Isar 2, Emsland und Neckarwestheim 2 abgeschaltet. Nach über 60 Jahren endete die kommerzielle Kernkraft in Deutschland.",
    more: "Ursprünglich sollten sie Ende 2022 vom Netz. Wegen der Energiekrise nach Russlands Angriff auf die Ukraine verlängerte die Ampel per Richtlinienkompetenz des Kanzlers um dreieinhalb Monate. Die Debatte über einen Wiedereinstieg hält an; ein Rückbau ist aber teils schon weit fortgeschritten." },
  { id: "pde-123", cat: "politik", topic: "Energie & Klima", type: "order", emoji: "⏱️", level: 2,
    q: "Ordne die Etappen der deutschen Atompolitik.",
    items: ["Atomkonsens unter Rot-Grün", "Laufzeitverlängerung unter Schwarz-Gelb", "Fukushima: beschleunigter Ausstieg", "Abschaltung der letzten drei AKW"],
    explain: "2000/2002 Atomkonsens (Schröder), Herbst 2010 Laufzeitverlängerung (Merkel), nach Fukushima im März 2011 Kehrtwende mit Ausstieg bis 2022, Abschaltung im April 2023." },
  { id: "pde-124", cat: "politik", topic: "Energie & Klima", type: "quiz", emoji: "🌍", level: 1,
    q: "Bis wann will Deutschland laut Klimaschutzgesetz klimaneutral sein?",
    options: ["2045", "2050", "2035", "2060"],
    answer: 0,
    explain: "Netto-Treibhausgasneutralität bis 2045 – fünf Jahre vor dem EU-Ziel 2050. Die Ampel-Vorgängerin (GroKo) zog das Ziel 2021 nach dem Klimabeschluss des Bundesverfassungsgerichts von 2050 vor." },
  { id: "pde-125", cat: "politik", topic: "Energie & Klima", type: "number", emoji: "🎯", level: 2,
    value: "−65 %", label: "Treibhausgase bis 2030 gegenüber 1990",
    text: "Zwischenziel im Klimaschutzgesetz, für 2040 sind −88 % vorgesehen. 2024 lag Deutschland bei rund −48 %.",
    more: "Ein großer Teil der bisherigen Minderung kam aus dem Stromsektor (Kohle raus, Erneuerbare rein) und früh aus dem Zusammenbruch der DDR-Industrie. Schwieriger sind Verkehr und Gebäude – dort stagnierten die Emissionen lange." },
  { id: "pde-126", cat: "politik", topic: "Energie & Klima", type: "fact", emoji: "🏭", level: 2,
    title: "Kohleausstieg spätestens 2038",
    text: "Das Kohleausstiegsgesetz von 2020 legt das Ende der Kohleverstromung auf spätestens 2038 fest. Im Rheinischen Revier soll RWE bereits 2030 aussteigen. Die Kohleregionen erhalten bis zu 40 Mrd. € Strukturhilfen.",
    more: "Spannungsfeld: Klimaschutz vs. Versorgungssicherheit vs. Arbeitsplätze in der Lausitz und im Rheinland. Für Versorgungssicherheit ohne Kohle und Atom braucht es neue, wasserstofffähige Gaskraftwerke als Reserve – deren Ausschreibung ist ein zentrales Projekt der Regierung Merz." },
  { id: "pde-127", cat: "politik", topic: "Energie & Klima", type: "quiz", emoji: "☀️", level: 2,
    q: "Welchen Anteil hatten erneuerbare Energien 2024 am deutschen Bruttostromverbrauch?",
    options: ["Rund ein Viertel", "Rund ein Drittel", "Rund 40 %", "Gut die Hälfte"],
    answer: 3,
    explain: "Rund 54 %, vor allem Wind und Solar. Ziel sind 80 % bis 2030. Beim gesamten Energieverbrauch (inkl. Wärme und Verkehr) ist der Anteil aber deutlich geringer – dort liegt die eigentliche Herausforderung." },
  { id: "pde-128", cat: "politik", topic: "Energie & Klima", type: "truefalse", emoji: "📉", level: 3,
    q: "Seit der Novelle 2024 muss jeder Sektor (z. B. Verkehr) seine eigenen Jahresziele einhalten, sonst wird automatisch ein Sofortprogramm fällig.",
    answer: false,
    explain: "Genau das wurde 2024 abgeschafft: Statt starrer Sektorziele zählt nun eine sektorübergreifende, mehrjährige Gesamtbetrachtung. Überschreitet die Projektion das Budget zwei Jahre in Folge, muss die Regierung nachsteuern. Kritiker sehen darin eine Entlastung v. a. des Verkehrsministeriums." },
  { id: "pde-129", cat: "politik", topic: "Energie & Klima", type: "whatif", emoji: "⛽", level: 3,
    q: "Was passiert, wenn der CO₂-Preis auf Benzin und Heizöl steigt?",
    steps: ["Tanken und Heizen werden teurer", "Anreiz für E-Auto und Wärmepumpe", "Belastung trifft Geringverdiener stark", "Debatte: Rückgabe per Klimageld"],
    text: "Seit 2021 gilt ein nationaler CO₂-Preis (2025: 55 € pro Tonne), der in einen EU-Emissionshandel für Gebäude und Verkehr übergehen soll. Ökonomen halten ihn für effizient – politisch heikel ist die soziale Verteilung. Ein pauschales Klimageld wurde bisher nicht eingeführt." },
  { id: "pde-130", cat: "politik", topic: "Energie & Klima", type: "flashcard", emoji: "🔥", level: 2,
    term: "Gebäudeenergiegesetz („Heizungsgesetz“)",
    def: "Seit 2024 müssen neu eingebaute Heizungen grundsätzlich zu 65 % mit erneuerbaren Energien laufen. In Bestandsgebäuden greift die Pflicht erst nach der kommunalen Wärmeplanung (bis spätestens 2028).",
    example: "Der Streit darum 2023 gilt als Wendepunkt in der Popularität der Ampel. Union und SPD haben vereinbart, das Gesetz zu reformieren (Stand 2025)." },

  // ── Sicherheit & Bundeswehr ──
  { id: "pde-131", cat: "politik", topic: "Bundeswehr", type: "event", emoji: "🪖", level: 1, year: "2022",
    title: "Zeitenwende-Rede von Olaf Scholz",
    text: "Drei Tage nach Russlands Großangriff auf die Ukraine kündigte Scholz am 27. Februar 2022 im Bundestag ein Sondervermögen von 100 Mrd. € für die Bundeswehr an und versprach, künftig das NATO-Ziel von 2 % zu erfüllen.",
    more: "Ein Bruch mit Jahrzehnten deutscher Zurückhaltung: Waffenlieferungen in ein Kriegsgebiet, Abkehr von russischem Gas, Aufrüstung. Das Sondervermögen wurde im Juni 2022 im Grundgesetz verankert (Art. 87a). Kritik: Bestellungen und Beschaffung liefen anfangs langsam an." },
  { id: "pde-132", cat: "politik", topic: "Bundeswehr", type: "quiz", emoji: "🛡️", level: 1,
    q: "Was besagt das NATO-Ziel von Wales 2014?",
    options: ["Mitglieder sollen 2 % ihres BIP für Verteidigung ausgeben", "Jedes Mitglied stellt 2 % seiner Bevölkerung als Soldaten", "2 % des Haushalts gehen an die NATO-Zentrale", "Atomwaffen in allen Mitgliedstaaten"],
    answer: 0,
    explain: "Bis 2024 sollten sich alle Mitglieder auf 2 % des BIP zubewegen. Deutschland erreichte das 2024 erstmals seit Jahrzehnten – auch dank des Sondervermögens. Davor lag es lange bei rund 1,2–1,5 %." },
  { id: "pde-133", cat: "politik", topic: "Bundeswehr", type: "number", emoji: "📈", level: 3,
    value: "5 %", label: "Neues NATO-Ziel bis 2035 (Gipfel Den Haag 2025)",
    text: "3,5 % des BIP für Kernverteidigung plus 1,5 % für verteidigungsrelevante Infrastruktur und Resilienz. Deutschland will die 3,5 % bereits deutlich vor 2035 erreichen.",
    more: "Zum Vergleich: Bei rund 4,3 Bio. € BIP entspricht 1 % etwa 43 Mrd. €. 3,5 % wären also rund 150 Mrd. € im Jahr – ermöglicht durch die Ausnahme von der Schuldenbremse seit März 2025." },
  { id: "pde-134", cat: "politik", topic: "Bundeswehr", type: "truefalse", emoji: "📜", level: 1,
    q: "Die Wehrpflicht wurde 2011 abgeschafft.",
    answer: false,
    explain: "Sie wurde zum 1. Juli 2011 nur ausgesetzt, nicht abgeschafft: Art. 12a GG erlaubt sie weiterhin. Im Spannungs- oder Verteidigungsfall lebt sie nach dem Wehrpflichtgesetz automatisch wieder auf." },
  { id: "pde-135", cat: "politik", topic: "Bundeswehr", type: "fact", emoji: "📋", level: 2,
    title: "Neuer Wehrdienst (Stand Anfang 2026)",
    text: "Ende 2025 beschloss der Bundestag ein neues Wehrdienstgesetz: Junge Menschen erhalten einen Fragebogen zu Eignung und Motivation, für Männer ist die Antwort Pflicht. Der Dienst selbst bleibt zunächst freiwillig.",
    more: "Ziel ist, die Truppe von rund 180.000 auf deutlich über 200.000 aktive Soldaten zu vergrößern, wie es die NATO-Planungen verlangen. Reicht die Zahl der Freiwilligen nicht, kann der Bundestag per Gesetz eine Bedarfswehrpflicht aktivieren. Umstritten zwischen Union (eher Pflicht) und Teilen der SPD (Freiwilligkeit zuerst)." },
  { id: "pde-136", cat: "politik", topic: "Bundeswehr", type: "flashcard", emoji: "🏛️", level: 2,
    term: "Parlamentsarmee",
    def: "Bewaffnete Auslandseinsätze der Bundeswehr brauchen grundsätzlich die vorherige Zustimmung des Bundestags (BVerfG 1994, Parlamentsbeteiligungsgesetz). Mandate sind befristet und begrenzt.",
    example: "Bei Gefahr im Verzug darf die Regierung handeln und muss die Zustimmung nachholen – etwa bei Evakuierungen wie in Kabul 2021." },
  { id: "pde-137", cat: "politik", topic: "Bundeswehr", type: "whatif", emoji: "🚨", level: 3,
    q: "Was passiert, wenn der Verteidigungsfall festgestellt wird?",
    steps: ["Bundestag stellt ihn mit 2/3 fest", "Bundesrat muss zustimmen", "Kanzler erhält die Befehlsgewalt", "Wehrpflicht lebt automatisch auf"],
    text: "Art. 115a ff. GG regeln die Notverfassung: Wahlperioden verlängern sich, ist das Parlament handlungsunfähig, übernimmt der Gemeinsame Ausschuss (2/3 Bundestag, 1/3 Bundesrat). Seit 1949 wurde der Verteidigungsfall nie festgestellt." },
  { id: "pde-138", cat: "politik", topic: "Bundeswehr", type: "quiz", emoji: "📯", level: 2,
    q: "Wer ist Anlaufstelle für Beschwerden von Soldaten und kontrolliert die Bundeswehr im Auftrag des Bundestags?",
    options: ["Der Generalinspekteur", "Der Bundespräsident", "Der Militärische Abschirmdienst", "Die bzw. der Wehrbeauftragte"],
    answer: 3,
    explain: "Der Wehrbeauftragte (seit 2025 Henning Otte, CDU) ist Hilfsorgan des Bundestags. Sein Jahresbericht zeigt regelmäßig Mängel bei Ausrüstung, Personal und Infrastruktur auf. Jeder Soldat darf sich direkt an ihn wenden." },

  // ── Digitalisierung & Verwaltung ──
  { id: "pde-139", cat: "politik", topic: "Digitalisierung", type: "fact", emoji: "💻", level: 1,
    title: "Onlinezugangsgesetz: Ziel klar verfehlt",
    text: "Das OZG von 2017 verpflichtete Bund, Länder und Kommunen, bis Ende 2022 rund 575 Verwaltungsleistungen online anzubieten. Flächendeckend gelang das nur für einen Bruchteil.",
    more: "Ursachen: föderale Zersplitterung (jede Ebene eigene IT), fehlende Standards, Schriftform-Erfordernisse, Fachkräftemangel. Das OZG 2.0 (2024) setzt auf einheitliche Standards und die BundID als zentrales Konto. Deutschland liegt in EU-Vergleichen zur digitalen Verwaltung meist nur im Mittelfeld." },
  { id: "pde-140", cat: "politik", topic: "Digitalisierung", type: "quiz", emoji: "🆕", level: 1,
    q: "Welches Ministerium wurde 2025 mit der Regierung Merz neu geschaffen?",
    options: ["Ministerium für Digitales und Staatsmodernisierung", "Ministerium für Migration", "Ministerium für Raumfahrt", "Ministerium für Energie"],
    answer: 0,
    explain: "Geleitet von dem parteilosen Manager Karsten Wildberger. Es bündelt Zuständigkeiten, die vorher auf Innen-, Wirtschafts- und Verkehrsministerium verteilt waren – ein Versuch, das Ressortprinzip-Problem „alle zuständig, keiner verantwortlich“ zu lösen." },
  { id: "pde-141", cat: "politik", topic: "Digitalisierung", type: "truefalse", emoji: "🩺", level: 2,
    q: "Gesetzlich Versicherte bekommen die elektronische Patientenakte (ePA) automatisch, wenn sie nicht widersprechen.",
    answer: true,
    explain: "Seit 2025 gilt die „ePA für alle“ nach dem Opt-out-Prinzip; bundesweit nutzbar seit Ende April 2025. Zuvor war sie freiwillig (Opt-in) und wurde von weniger als 1 % genutzt – ein Lehrstück, wie stark Voreinstellungen (Defaults) wirken." },
  { id: "pde-142", cat: "politik", topic: "Digitalisierung", type: "flashcard", emoji: "🔁", level: 3,
    term: "Once-Only-Prinzip",
    def: "Bürger und Unternehmen sollen Daten nur einmal an den Staat übermitteln müssen; Behörden tauschen sie (mit Zustimmung) untereinander aus. Grundlage ist die Registermodernisierung.",
    example: "Seit dem Registermodernisierungsgesetz 2021 dient die Steuer-ID als übergreifende Identifikationsnummer in wichtigen Registern." },
  { id: "pde-143", cat: "politik", topic: "Digitalisierung", type: "whatif", emoji: "🧩", level: 2,
    q: "Was passiert, wenn jede Kommune eigene Software für dieselbe Leistung kauft?",
    steps: ["Hunderte inkompatible Insellösungen", "Daten fließen nicht zwischen Behörden", "Bürger müssen Nachweise neu einreichen", "Hohe Kosten, langsame Digitalisierung"],
    text: "Genau das ist ein Kernproblem der deutschen Verwaltungsdigitalisierung. Gegenmittel: „Einer für Alle“ – ein Land entwickelt eine Lösung, andere übernehmen sie – sowie verbindliche Bundesstandards." },

  // ── Lobbyismus & Transparenz ──
  { id: "pde-144", cat: "politik", topic: "Lobbyismus", type: "fact", emoji: "📒", level: 1,
    title: "Lobbyregister seit 2022",
    text: "Wer gegenüber Bundestag oder Bundesregierung Interessen vertritt, muss sich öffentlich registrieren: Auftraggeber, Themen, finanzieller Aufwand. Seit 2024 gilt eine verschärfte Fassung mit mehr Angaben.",
    more: "Lobbyismus an sich ist legitim – Verbände, Gewerkschaften, NGOs und Unternehmen liefern Fachwissen. Problematisch wird er durch Intransparenz und ungleiche Ressourcen. Kritiker fordern zusätzlich einen „exekutiven Fußabdruck“: offenlegen, wer an einem Gesetzentwurf mitgeschrieben hat." },
  { id: "pde-145", cat: "politik", topic: "Lobbyismus", type: "flashcard", emoji: "🚪", level: 2,
    term: "Karenzzeit",
    def: "Wartezeit für ehemalige Regierungsmitglieder vor einem Wechsel in die Wirtschaft. Bundesminister und parlamentarische Staatssekretäre müssen neue Jobs melden; die Regierung kann bis zu 18 Monate untersagen.",
    example: "Gegen den „Drehtür-Effekt“: Der Wechsel von Kanzleramtschef Ronald Pofalla zur Deutschen Bahn löste die Regelung von 2015 mit aus." },
  { id: "pde-146", cat: "politik", topic: "Lobbyismus", type: "quiz", emoji: "😷", level: 2,
    q: "Was war eine Folge der „Maskenaffäre“ von 2021?",
    options: ["Abgeordnete dürfen keine Nebenjobs mehr haben", "Abgeordnete müssen Nebeneinkünfte nun betragsgenau offenlegen", "Das Lobbyregister wurde abgeschafft", "Der Bundestag wurde aufgelöst"],
    answer: 1,
    explain: "Unionsabgeordnete hatten Provisionen für die Vermittlung von Corona-Masken kassiert. Danach wurden Regeln verschärft: Nebeneinkünfte ab 1.000 € im Monat bzw. 3.000 € im Jahr werden betragsgenau veröffentlicht, bezahlte Lobbytätigkeit für Abgeordnete ist verboten." },
  { id: "pde-147", cat: "politik", topic: "Lobbyismus", type: "truefalse", emoji: "⚖️", level: 3,
    q: "Die Bestechung von Bundestagsabgeordneten ist erst seit 2014 umfassend strafbar.",
    answer: true,
    explain: "Vorher war nur der Stimmenkauf bei Wahlen und Abstimmungen strafbar. Erst die Ratifizierung der UN-Konvention gegen Korruption führte zum erweiterten § 108e StGB. Da die Maskendeals davon nicht erfasst waren, kam 2024 noch § 108f (unzulässige Interessenwahrnehmung) hinzu." },
  { id: "pde-148", cat: "politik", topic: "Lobbyismus", type: "whatif", emoji: "🔄", level: 3,
    q: "Was passiert, wenn ein Minister direkt nach dem Amt zu einem Unternehmen aus seinem Ressort wechselt?",
    steps: ["Pflicht zur Anzeige bei der Regierung", "Gremium prüft Interessenkonflikte", "Bei Konflikt: Sperre bis zu 18 Monate", "Öffentlichkeit erfährt die Entscheidung"],
    text: "Die Sorge: Insiderwissen und Kontakte werden „versilbert“, oder Entscheidungen im Amt werden mit Blick auf den künftigen Arbeitgeber getroffen. Die Sperre schafft Abstand, verbietet den Wechsel aber nicht dauerhaft." },

  // ── Politische Begriffe ──
  { id: "pde-149", cat: "politik", topic: "Begriffe", type: "flashcard", emoji: "🧠", level: 1,
    term: "Fraktionsdisziplin vs. freies Mandat",
    def: "Abgeordnete sind laut Art. 38 GG an Aufträge und Weisungen nicht gebunden, nur ihrem Gewissen. Trotzdem erwarten Fraktionen geschlossenes Abstimmen – das ist Fraktionsdisziplin, ein rechtlich erzwingbarer „Fraktionszwang“ existiert nicht.",
    example: "Wer abweicht, riskiert Ausschussposten oder den Listenplatz – aber nie sein Mandat." },
  { id: "pde-150", cat: "politik", topic: "Begriffe", type: "quiz", emoji: "🙏", level: 1,
    q: "Bei welcher Abstimmung wurde die Fraktionsdisziplin aufgehoben (Gewissensentscheidung)?",
    options: ["Organspende-Regelung 2020", "Bundeshaushalt 2024", "Sondervermögen Bundeswehr 2022", "Kanzlerwahl 2025"],
    answer: 0,
    explain: "Bei ethischen Fragen wie Organspende, Sterbehilfe oder Präimplantationsdiagnostik stimmen Abgeordnete traditionell fraktionsübergreifend nach Gewissen ab, oft mit Gruppenanträgen. 2020 scheiterte die Widerspruchslösung, die Zustimmungslösung blieb." },
  { id: "pde-151", cat: "politik", topic: "Begriffe", type: "truefalse", emoji: "🚶", level: 1,
    q: "Tritt ein Abgeordneter aus seiner Partei aus, verliert er automatisch sein Mandat.",
    answer: false,
    explain: "Das Mandat gehört der Person, nicht der Partei (freies Mandat). Er kann fraktionslos weitermachen oder in eine andere Fraktion wechseln. Erst wenn er sein Mandat niederlegt, rückt jemand von der Landesliste nach." },
  { id: "pde-152", cat: "politik", topic: "Begriffe", type: "fact", emoji: "🗣️", level: 1,
    title: "Die Rolle der Opposition",
    text: "Im parlamentarischen System verläuft die Gewaltenteilung praktisch zwischen Regierung plus Mehrheit einerseits und Opposition andererseits. Die Opposition kontrolliert, kritisiert und bietet Alternativen.",
    more: "Ihre Werkzeuge: Kleine und Große Anfragen, Aktuelle Stunden, Untersuchungsausschüsse (ab 25 % der Abgeordneten), Normenkontrollklagen in Karlsruhe (ebenfalls 25 %). Ist die Opposition sehr klein – wie bei Großen Koalitionen – werden diese Hürden zum Problem; 2014 wurden die Minderheitenrechte deshalb zeitweise angepasst." },
  { id: "pde-153", cat: "politik", topic: "Begriffe", type: "quiz", emoji: "🔢", level: 1,
    q: "Was bedeutet „Kanzlermehrheit“?",
    options: ["Die Mehrheit der anwesenden Abgeordneten", "Zwei Drittel der Stimmen", "Die Mehrheit im Bundesrat", "Die Mehrheit aller Mitglieder des Bundestags"],
    answer: 3,
    explain: "Absolute Mehrheit der gesetzlichen Mitgliederzahl: bei 630 Sitzen 316 Stimmen – egal, wie viele anwesend sind. Nötig u. a. für Kanzlerwahl, Misstrauensvotum und das Überstimmen eines Bundesrats-Einspruchs." },
  { id: "pde-154", cat: "politik", topic: "Begriffe", type: "flashcard", emoji: "⚖️", level: 1,
    term: "Gewaltenteilung (horizontal und vertikal)",
    def: "Horizontal: Legislative (Parlament), Exekutive (Regierung, Verwaltung), Judikative (Gerichte). Vertikal: Aufteilung der Macht zwischen Bund, Ländern und Kommunen.",
    example: "Der Föderalismus ist also selbst ein Instrument der Machtbegrenzung – darum schützt ihn die Ewigkeitsklausel." },
  { id: "pde-155", cat: "politik", topic: "Begriffe", type: "quiz", emoji: "🧾", level: 3,
    q: "Was ist ein „imperatives Mandat“ – und ist es im Bundestag erlaubt?",
    options: ["Ein Mandat auf Lebenszeit – erlaubt", "Ein Nachrückermandat – erlaubt", "Bindung des Abgeordneten an Weisungen von Partei oder Wählern – verboten", "Ein Direktmandat – erlaubt"],
    answer: 2,
    explain: "Art. 38 GG schließt es aus: Abgeordnete sind „Vertreter des ganzen Volkes“. Verträge, in denen sich Abgeordnete zu bestimmtem Abstimmungsverhalten verpflichten oder Blanko-Rücktrittserklärungen abgeben, sind unwirksam." },
);
